// command-guard: hold risky Bash commands, show what they would destroy, ask first.
//
// THIS IS A SAFETY NET, NOT A PERMISSION SYSTEM. It only ever adds a question; it never
// allows anything the normal permission prompt would not. Keep your permissions on.
//
// HOW THE CALL IS HELD OPEN (the one engine detail that matters here):
//   A hook has a 10 s budget of its OWN time, but the clock stops while a `next` call or
//   any `$` call is in flight (HookBudget in the API types). `$.ui.ask` is a `$` call
//   that waits for a person, so it can wait minutes at no cost. A pane with Proceed /
//   Cancel buttons would NOT work: its press arrives as a separate event, and a hook
//   waiting on a bare promise for that press burns its own budget and is timed out
//   after 10 s. So the question goes through the engine's own question dialog; the first
//   option is Cancel, which is the one the dialog highlights, so Enter means no.
//   There is no timeout of our own: the dialog stays until answered; an interrupt
//   (Esc, or the turn being stopped) rejects the ask and that is treated as Cancel.
import { atom, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import { classify } from './classify'
import { LEVELS, LEVEL_MEANING, asLevel, failClosedReason, isBelowBar, readConfig } from './config'
import type { Level } from './config'
import { denyText, dialogText, toastText } from './format'
import { measureAll } from './measure'
import type { Run } from './measure'
import { looksWindows, unmeasured } from './windows'

const PROBE_TIMEOUT_MS = 20_000
const COMMAND = 'command-guard'

/** Mirror of the persisted runtime level (`$.store` 'level'), so other mods can read it with $.state.get. */
const levelAtom = atom({ plugin: 'command-guard', key: 'level' } as const, 'medium')

/** The level in force: the person's runtime choice if there is one, else the `askFrom` setting. */
async function levelNow($: EngineInterface, fallback: Level): Promise<Level> {
  return asLevel(await safe(() => $.store.get('level'))) ?? fallback
}

const describe = (l: Level): string => `${l} (${LEVEL_MEANING[l]})`

async function runCommand($: EngineInterface, args: string, fallback: Level): Promise<string> {
  const word = args.trim().toLowerCase()
  const current = await levelNow($, fallback)
  if (word === '') {
    return [
      `Blast radius · ${describe(current)}`,
      `Levels: ${LEVELS.map(l => `${l} = ${LEVEL_MEANING[l]}`).join(' · ')} · /command-guard <level> to change`,
    ].join('\n')
  }
  const next = asLevel(word)
  if (next === undefined) return `Blast radius · "${args.trim().slice(0, 30)}" is not a level, nothing changed · use off, low, medium or high (now ${current})`
  try {
    await $.store.set('level', next)
    await update($, levelAtom, () => next)
  } catch {
    return 'Blast radius · that did not work, nothing changed'
  }
  return `Blast radius · ${describe(next)}`
}

export const register: Register = (on, options) => {
  const cfg = readConfig(options)

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    // The person's runtime level overrides the setting; off is fail-open, before anything is classified.
    const level = await levelNow($, cfg.askFrom)
    if (level === 'off') return next(e)
    const cwd = await safe(() => $.session.cwd())
    const home = await safe(() => $.env.get('HOME'))
    const found = classify(e.command, { cwd, home, extraPatterns: cfg.extraPatterns })
    if (found.length === 0) return next(e)

    const run: Run = (argv, dir, opts) => $.process.run(argv, { cwd: dir, timeoutMs: opts?.timeoutMs ?? PROBE_TIMEOUT_MS })
    // WINDOWS: the probes below are Unix `find` / `du`. On native Windows `find` is a different program (text search), so an
    // empty answer would look like "nothing there" and a destructive command would pass unasked. Never do that: hold
    // the command with an honest "cannot measure here" instead. (Conditional findings such as `> file` need a file check
    // we cannot make there, so they pass through rather than asking about every redirect.)
    const win = await isWindows($, cwd, home)
    const { reports, unlisted } = win ? unmeasured(found) : await measureAll(run, found, { maxListed: cfg.maxListed, home, cwd })
    if (reports.length === 0 && unlisted === 0) return next(e) // conditions not met, e.g. `> new-file`
    // Below the `askFrom` bar nothing is shown: a command whose every part is lower risk goes through. A part that
    // was not checked (unlisted) or whose level is unknown always asks.
    if (isBelowBar(reports.map(r => r.risk?.level ?? 'unknown'), unlisted, level)) return next(e)

    const verdict = await confirm($, dialogText(e.command, reports, unlisted, cwd, cfg.maxListed))
    if (verdict.isYes) {
      await safe(() => $.ui.status(undefined))
      return next(e)
    }
    const why = verdict.why

    const toast = toastText(reports)
    await safe(() => $.ui.toast(toast, { timeoutMs: 8000 }))
    await safe(() => $.ui.status(toast))
    await safe(() => $.clock.after(30_000, () => void safe(() => $.ui.status(undefined))))
    return { deny: denyText(why, e.command, reports) }
  }).catch(($, e, next) => {
    // FAIL CLOSED, but only where the text itself looks destructive. The classifier or the
    // measurer (or the dialog code) threw, or the hook outran its budget: if the command
    // matches the coarse FALLBACK_RISKY regex or one of the user's own patterns we refuse
    // rather than guess; anything else goes through, so a bug here cannot wedge ordinary
    // work. Where `next` was already called (the user pressed Proceed) we just replay it.
    if (next.called) return next(e)
    const deny = failClosedReason((e as { command?: unknown }).command, cfg)
    return deny === undefined ? next(e) : { deny }
  })

  on('session.start', async ($, e, next) => {
    const level = await levelNow($, cfg.askFrom)
    await safe(() => update($, levelAtom, () => level)) // the mirror starts from what is stored, else the setting
    await safe(() =>
      $.command.register({
        name: COMMAND,
        description: 'Change how much command-guard asks about: /command-guard [off|low|medium|high]',
        argumentHint: '[off|low|medium|high]',
      }),
    ) // fail-open: without the command the setting still works
    if (cfg.badPatterns.length)
      await safe(() =>
        $.ui.toast(`command-guard: ignored invalid extra patterns: ${cfg.badPatterns.map(p => p.replace(/\s+/g, ' ')).join(', ')}`, { timeoutMs: 10_000 }),
      )
    return next(e)
  })

  on('command.run', { command: COMMAND }, async ($, e) => ({ text: await runCommand($, e.args, cfg.askFrom) })).catch(() => ({
    text: 'Blast radius · that did not work, nothing changed',
  }))
}

async function isWindows($: EngineInterface, cwd: string | undefined, home: string | undefined): Promise<boolean> {
  if (looksWindows(cwd) || looksWindows(home)) return true
  return (await safe(() => $.env.get('OS'))) === 'Windows_NT'
}

type Verdict = { isYes: true } | { isYes: false; why: string }

// Only an exact "Proceed" lets the command run; Cancel, free text under Other, Esc, a
// rejected dialog and a run with no surface at all are all a no.
async function confirm($: EngineInterface, text: string): Promise<Verdict> {
  const surfaces = await safe(() => $.session.surfaces())
  if (surfaces !== undefined && surfaces.length === 0) return { isYes: false, why: 'no screen to ask on in this run' }
  try {
    const answer = await $.ui.ask(text, {
      options: ['Cancel', 'Proceed'], // Cancel first: the dialog opens on it
      header: 'Blast radius',
    })
    if (answer === 'Proceed') return { isYes: true }
    return { isYes: false, why: answer === 'Cancel' ? 'cancelled in the dialog' : `answered "${answer.slice(0, 40).replace(/\s+/g, ' ')}", not Proceed` }
  } catch {
    return { isYes: false, why: 'no answer: dialog dismissed, or no one to ask' }
  }
}

async function safe<T>(f: () => T | Promise<T>): Promise<T | undefined> {
  try {
    return await f()
  } catch {
    return undefined
  }
}

files.hooks/classify.ts:
// The classifier: a PURE function from a shell command line to the list of risky
// simple commands in it. No `$`, no file access: whether a target really exists is
// the measurer's business. Anything it cannot see through (a variable as command
// name, nesting deeper than DEPTH_LIMIT) is reported rather than waved through.
import { lex } from './lex'
import type { Tok, Word } from './lex'

export type Kind =
  | 'rm' | 'find' | 'truncate' | 'shred' | 'dd' | 'mkfs' | 'redirect' | 'overwrite' | 'chmod'
  | 'git-clean' | 'git-reset' | 'git-discard' | 'git-push' | 'git-branch' | 'git-stash'
  | 'sql' | 'r' | 'cargo-clean' | 'custom' | 'opaque'

/** A path a command acts on. `path` is absolute and normalised; absent when `unresolved` says why. */
export type Target = { raw: string; path?: string; glob: boolean; unresolved?: string }

export type Finding = {
  kind: Kind
  reason: string // one line, shown under the command
  command: string // the simple command as the shell would see it
  cwd?: string // directory it runs in, undefined when a `cd` could not be followed
  args: string[] // words after the command name (after the git subcommand for git)
  targets: Target[]
  critical?: boolean // targets / or the home directory
  viaXargs?: boolean // the real operands arrive on stdin
  // Held only if the measurer finds the condition true (the classifier cannot stat files).
  conditional?: 'non-empty-file' | 'dest-exists'
}

export type ClassifyContext = {
  cwd?: string // the session's working directory
  home?: string // for `~`
  extraPatterns?: readonly RegExp[] // the user's own, tested against the whole command line
}

type State = { cwd: string | undefined }
type Ctx = ClassifyContext & { out: Finding[] }

const DEPTH_LIMIT = 6

export function classify(command: string, ctx: ClassifyContext = {}): Finding[] {
  const out: Finding[] = []
  scan(command, { cwd: ctx.cwd }, { ...ctx, out }, 0)
  for (const re of ctx.extraPatterns ?? [])
    if (re.test(command))
      out.push(finding('custom', `matches your extra pattern ${re}`, [], [], undefined, command))
  return out
}

// ---- paths ---------------------------------------------------------------------

export function normalize(path: string): string {
  const parts: string[] = []
  for (const p of path.split('/'))
    if (p === '..') parts.pop()
    else if (p !== '' && p !== '.') parts.push(p)
  return '/' + parts.join('/')
}

function target(w: Word, st: State, ctx: ClassifyContext): Target {
  const base = { raw: w.text, glob: w.glob }
  if (w.dynamic) return { ...base, unresolved: 'contains a variable or command substitution' }
  if (w.text === '') return { ...base, unresolved: 'empty path' }
  let t = w.text
  if (w.tilde) {
    if (t !== '~' && !t.startsWith('~/')) return { ...base, unresolved: 'another user\'s home' }
    if (!ctx.home) return { ...base, unresolved: 'home directory unknown' }
    t = ctx.home + t.slice(1)
  }
  if (!t.startsWith('/')) {
    if (!st.cwd) return { ...base, unresolved: 'relative path after a cd that could not be followed' }
    t = `${st.cwd}/${t}`
  }
  return { ...base, path: normalize(t) }
}

const isCritical = (t: Target, home?: string) =>
  /^(\/|~\/?|\$HOME\/?|\.|\.\/|\.\.|\.\.\/)\*?$/.test(t.raw) ||
  t.path === '/' || (home !== undefined && t.path === home) || t.raw === '/*'

// ---- argument helpers --------------------------------------------------------------

type Flags = { short: Set<string>; long: Set<string>; operands: Word[] }

// Options may appear anywhere before `--` (GNU permutes). `valued` lists short options
// that take a separate value word, `valuedLong` the long ones; their values are not operands.
function flags(args: Word[], valued = '', valuedLong: string[] = []): Flags {
  const f: Flags = { short: new Set(), long: new Set(), operands: [] }
  let ended = false
  for (let k = 0; k < args.length; k++) {
    const t = args[k]!.text
    if (ended || !t.startsWith('-') || t === '-') f.operands.push(args[k]!)
    else if (t === '--') ended = true
    else if (t.startsWith('--')) {
      const name = t.slice(2).split('=')[0]!
      f.long.add(name)
      if (!t.includes('=') && valuedLong.includes(name)) k++
    } else {
      for (let c = 1; c < t.length; c++) {
        f.short.add(t[c]!)
        if (valued.includes(t[c]!)) {
          if (c === t.length - 1) k++
          break
        }
      }
    }
  }
  return f
}

const base = (s: string) => s.slice(s.lastIndexOf('/') + 1)
const isAssignment = (w: Word) => /^[A-Za-z_][A-Za-z0-9_]*\+?=/.test(w.text)
const show = (w: Word) => (/[\s'"$;|&<>()]/.test(w.text) || w.text === '' ? JSON.stringify(w.text) : w.text)

function finding(
  kind: Kind, reason: string, words: Word[], targets: Target[], cwd: string | undefined,
  commandText?: string, extra: Partial<Finding> = {},
): Finding {
  return {
    kind, reason, command: commandText ?? words.map(show).join(' '), cwd,
    args: [], targets, ...extra,
  }
}

// ---- wrappers: sudo, env, time, xargs ... -------------------------------------------

// `valued`: short options of the wrapper that take a value; `positional`: operands to skip.
const WRAPPERS: Record<string, { valued: string; positional?: number }> = {
  sudo: { valued: 'ughpCDrtTUR' }, doas: { valued: 'uC' }, env: { valued: 'uCS' },
  time: { valued: 'fo' }, nice: { valued: 'n' }, ionice: { valued: 'cnpt' }, nohup: { valued: '' },
  command: { valued: '' }, builtin: { valued: '' }, exec: { valued: 'a' }, stdbuf: { valued: 'ioe' },
  setsid: { valued: '' }, caffeinate: { valued: 'tw' }, chronic: { valued: '' }, unbuffer: { valued: '' },
  timeout: { valued: 'sk', positional: 1 }, gtimeout: { valued: 'sk', positional: 1 },
  xargs: { valued: 'INPdaELsJRS' },
}
// Words that start a command in compound statements: `if x; then rm -rf y; fi`.
const RESERVED = new Set(['if', 'then', 'else', 'elif', 'while', 'until', 'do', '!', '{', 'function'])

function skipWrapperOptions(words: Word[], from: number, spec: { valued: string; positional?: number }): number {
  let i = from
  while (i < words.length) {
    const t = words[i]!.text
    if (t === '--') return i + 1 + (spec.positional ?? 0)
    if (isAssignment(words[i]!)) i++
    else if (t.startsWith('-') && t.length > 1) {
      if (!t.startsWith('--'))
        for (let c = 1; c < t.length; c++)
          if (spec.valued.includes(t[c]!)) {
            if (c === t.length - 1) i++
            break
          }
      i++
    } else break
  }
  return i + (spec.positional ?? 0)
}

type Unwrapped = { name: string; args: Word[]; viaXargs: boolean; dynamicName: boolean; words: Word[] }

function unwrap(all: Word[]): Unwrapped | undefined {
  let i = 0
  let viaXargs = false
  while (i < all.length) {
    const w = all[i]!
    if (isAssignment(w) || (!w.dynamic && RESERVED.has(w.text))) i++
    else if (w.dynamic)
      return { name: '', args: all.slice(i + 1), viaXargs, dynamicName: true, words: all.slice(i) }
    else {
      const name = base(w.text)
      const spec = WRAPPERS[name]
      if (!spec) return { name, args: all.slice(i + 1), viaXargs, dynamicName: false, words: all.slice(i) }
      if (name === 'xargs') viaXargs = true
      i = skipWrapperOptions(all, i + 1, spec)
    }
  }
  return undefined
}

// ---- the walk: lists, pipelines, subshells, cd -----------------------------------------

type Simple = {
  words: Word[]
  redirs: { op: string; fd?: string; target?: Word }[]
  heredocs: string[]
}
const emptyCmd = (): Simple => ({ words: [], redirs: [], heredocs: [] })

function scan(src: string, st: State, ctx: Ctx, depth: number): void {
  if (depth > DEPTH_LIMIT) {
    ctx.out.push(finding('opaque', 'nested too deeply to analyse', [], [], st.cwd, src.slice(0, 80)))
    return
  }
  walk(lex(src), st, ctx, depth)
}

function walk(toks: Tok[], st: State, ctx: Ctx, depth: number): void {
  let pipeline: Simple[] = []
  let cmd = emptyCmd()
  const endCmd = () => {
    if (cmd.words.length || cmd.redirs.length) pipeline.push(cmd)
    cmd = emptyCmd()
  }
  const endPipeline = () => {
    endCmd()
    if (pipeline.length) analyzePipeline(pipeline, st, ctx, depth)
    pipeline = []
  }
  for (let k = 0; k < toks.length; k++) {
    const tk = toks[k]!
    if (tk.t === 'word') cmd.words.push(tk.w)
    else if (tk.t === 'redir') {
      const next = toks[k + 1]
      const t = next?.t === 'word' ? next.w : undefined
      if (t) k++
      cmd.redirs.push({ op: tk.op, ...(tk.fd ? { fd: tk.fd } : {}), ...(t ? { target: t } : {}) })
      if (tk.body !== undefined) cmd.heredocs.push(tk.body)
      if (tk.op === '<<<' && t) cmd.heredocs.push(t.text)
    } else if (tk.op === '(') {
      const close = matchParen(toks, k)
      if (cmd.words.length === 0) {
        // A subshell: a `cd` inside it does not leak out.
        walk(toks.slice(k + 1, close), { ...st }, ctx, depth)
      }
      else endPipeline() // a function definition `f() { ... }`: its body is walked as ordinary commands
      k = close
    } else if (tk.op === ')') endPipeline() // `case x in a) ...`
    else if (tk.op === '|') endCmd()
    else endPipeline()
  }
  endPipeline()
}

function matchParen(toks: Tok[], open: number): number {
  let depth = 0
  for (let k = open; k < toks.length; k++) {
    const t = toks[k]!
    if (t.t === 'op' && t.op === '(') depth++
    else if (t.t === 'op' && t.op === ')' && --depth === 0) return k
  }
  return toks.length
}

const SQL_CLIENT = /^(psql|sqlite3?|mysql|mariadb|duckdb)$/

function analyzePipeline(cmds: Simple[], st: State, ctx: Ctx, depth: number): void {
  const single = cmds.length === 1
  // SQL fed through a pipe or heredoc belongs to the client at the end of the pipeline.
  const sqlText = cmds.some(c => SQL_CLIENT.test(unwrap(c.words)?.name ?? ''))
    ? cmds.flatMap(c => [...c.words.filter(w => !w.text.startsWith('--')).map(w => w.text), ...c.heredocs]).join(' ')
    : undefined
  for (const c of cmds) analyzeCommand(c, single ? st : { ...st }, ctx, depth, sqlText)
}

function analyzeCommand(c: Simple, st: State, ctx: Ctx, depth: number, sqlText?: string): void {
  for (const w of [...c.words, ...c.redirs.flatMap(r => (r.target ? [r.target] : []))])
    for (const sub of w.subs) scan(sub, { ...st }, ctx, depth + 1)
  clobbers(c, st, ctx)
  const u = unwrap(c.words)
  if (!u) return
  const text = u.words.map(show).join(' ')
  if (u.dynamicName) {
    const hot = u.args.some(a => /^-[a-zA-Z]*(rf|fr|Rf|fR)|^--recursive$/.test(a.text))
    if (hot)
      ctx.out.push(finding('opaque', 'the command name is a variable and the flags look like rm -rf', u.words, [], st.cwd, text))
    return
  }
  const here = { ...ctx, st, u, text, sqlText, depth }
  if (u.name === 'cd' || u.name === 'pushd') return cd(u.args, st, ctx)
  if (u.name === 'popd') return void (st.cwd = undefined)
  if (/^(ba|z|da|k|a)?sh$/.test(u.name)) return shellC(here)
  if (u.name === 'eval') return scan(u.args.map(a => a.text).join(' '), { ...st }, ctx, depth + 1)
  const hit = rules(here)
  if (hit) ctx.out.push(...hit)
}

function cd(args: Word[], st: State, ctx: ClassifyContext): void {
  const operands = flags(args).operands
  if (operands.length === 0) {
    st.cwd = ctx.home
    return
  }
  const t = target(operands[0]!, st, ctx)
  st.cwd = operands[0]!.text === '-' || t.glob ? undefined : t.path
}

type Here = Ctx & { st: State; u: Unwrapped; text: string; sqlText: string | undefined; depth: number }

// bash -c 'script', sh -lc "script"
function shellC(h: Here): void {
  const a = h.u.args
  const k = a.findIndex(w => /^-[a-zA-Z]*c[a-zA-Z]*$/.test(w.text))
  const script = k >= 0 ? a[k + 1] : undefined
  if (script) scan(script.text, { ...h.st }, h, h.depth + 1)
}

// `> file` and `&> file` truncate; `>>` appends. Whether the file exists is for the measurer.
function clobbers(c: Simple, st: State, ctx: Ctx): void {
  for (const r of c.redirs) {
    if (!['>', '>|', '&>'].includes(r.op) || !r.target) continue
    if (r.target.text.startsWith('/dev/')) continue
    const t = target(r.target, st, ctx)
    if (t.unresolved) continue // unknowable target: not held (documented limit)
    const text = [...c.words.map(show), r.op, show(r.target)].join(' ')
    ctx.out.push(finding('redirect', `${r.op} overwrites ${t.raw} if it already has content`, [], [t], st.cwd, text, {
      conditional: 'non-empty-file',
    }))
  }
}

// ---- the per-command rules ------------------------------------------------------------

function rules(h: Here): Finding[] | undefined {
  const { name, args } = h.u
  const one = (f: Finding | undefined) => (f ? [f] : undefined)
  const targets = (ws: Word[]) => ws.map(w => target(w, h.st, h))
  const mk = (kind: Kind, reason: string, ts: Word[], extra: Partial<Finding> = {}) => {
    const tt = targets(ts)
    return finding(kind, reason, h.u.words, tt, h.st.cwd, h.text, {
      args: args.map(a => a.text), critical: tt.some(t => isCritical(t, h.home)) || undefined,
      viaXargs: h.u.viaXargs || undefined, ...extra,
    })
  }

  switch (true) {
    case name === 'rm': {
      const f = flags(args)
      const recursive = f.short.has('r') || f.short.has('R') || f.long.has('recursive')
      const force = f.short.has('f') || f.long.has('force')
      const bulk = h.u.viaXargs || f.operands.some(o => o.glob)
      if (!recursive && !force && !bulk) return undefined // plain `rm file` is not held
      const why = recursive ? 'recursive delete (rm -r): not recoverable' : force ? 'forced delete (rm -f): not recoverable' : 'bulk delete by glob or xargs: not recoverable'
      return one(mk('rm', why, f.operands))
    }
    case name === 'find': return one(findRule(h, mk))
    case name === 'git': return gitRule(h, mk)
    case name === 'truncate': {
      const f = flags(args, 'sr', ['size', 'reference'])
      return one(mk('truncate', 'truncate cuts file contents', f.operands))
    }
    case name === 'shred': return one(mk('shred', 'shred overwrites file contents irrecoverably', flags(args, 'ns', ['iterations', 'size', 'random-source']).operands))
    case name === 'dd': {
      const of = args.find(a => a.text.startsWith('of='))
      if (!of) return undefined
      const path = of.text.slice(3)
      if (/^\/dev\/(null|zero|stdout|stderr|tty|fd\/\d+)$/.test(path)) return undefined
      return one(mk('dd', `dd writes over ${path}`, [{ ...of, text: path }]))
    }
    case /^(mkfs(\..+)?|mke2fs|newfs(_.+)?|mkswap|wipefs)$/.test(name):
      return one(mk('mkfs', `${name} destroys everything on the target device`, flags(args).operands.slice(-1)))
    case name === 'diskutil' && /^(erase|reformat|partitionDisk|zeroDisk|secureErase)/i.test(args[0]?.text ?? ''):
      return one(mk('mkfs', `diskutil ${args[0]!.text} destroys data on the target disk`, []))
    case /^(chmod|chown|chgrp)$/.test(name): {
      const f = flags(args)
      if (!f.long.has('recursive') && !f.short.has('R')) return undefined
      return one(mk('chmod', `${name} -R rewrites permissions or ownership of a whole tree`, f.long.has('reference') ? f.operands : f.operands.slice(1)))
    }
    case (name === 'mv' || name === 'cp'): {
      const f = flags(args, 't', ['target-directory'])
      if (!(f.short.has('f') || f.long.has('force')) || f.short.has('n') || f.long.has('no-clobber')) return undefined
      if (f.operands.length < 2) return undefined
      const dest = f.operands[f.operands.length - 1]!
      const srcs = f.operands.slice(0, -1)
      return one(mk('overwrite', `${name} -f replaces existing files without asking`, [dest], {
        conditional: 'dest-exists', args: srcs.map(s => s.text),
      }))
    }
    case name === 'cargo': {
      const sub = args.find(a => !a.text.startsWith('-') && !a.text.startsWith('+'))
      if (sub?.text !== 'clean') return undefined
      return one(mk('cargo-clean', 'cargo clean deletes the target/ directory (a full rebuild follows)', []))
    }
    case SQL_CLIENT.test(name): return one(sqlRule(h, mk))
    case name === 'R' || name === 'Rscript': return rRule(h, mk)
    default: return undefined
  }
}

type Mk = (kind: Kind, reason: string, ts: Word[], extra?: Partial<Finding>) => Finding

// find ... -delete / -exec rm
function findRule(h: Here, mk: Mk): Finding | undefined {
  const t = h.u.args.map(a => a.text)
  const del = t.includes('-delete')
  const exec = t.findIndex((x, k) => /^-(exec|execdir|ok|okdir)$/.test(x) && isRemover(t.slice(k + 1)))
  if (!del && exec < 0) return undefined
  return mk('find', del ? 'find -delete removes every match' : 'find -exec rm removes every match', [])
}

const isRemover = (rest: string[]) => {
  const c = base(rest[0] ?? '')
  return /^(rm|unlink|shred|rmdir)$/.test(c) || (/^(ba|z)?sh$/.test(c) && /\brm\b/.test(rest.slice(1).join(' ')))
}

const BROAD = /^(\.|\.\/|\*|:\/|:\/\.|:\/\*|:\(top\))$/

function gitRule(h: Here, mk: Mk): Finding[] | undefined {
  const a = h.u.args
  let i = 0
  let cwd = h.st.cwd
  while (i < a.length && a[i]!.text.startsWith('-')) {
    const t = a[i]!.text
    if (t === '-C' && a[i + 1]) {
      const r = target(a[i + 1]!, { cwd }, h)
      cwd = r.path
      i += 2
    } else i += ['-c', '--git-dir', '--work-tree', '--namespace'].includes(t) ? 2 : 1
  }
  const sub = a[i]?.text
  const rest = a.slice(i + 1)
  const f = flags(rest)
  const texts = rest.map(r => r.text)
  const make = (kind: Kind, reason: string, ts: Word[] = []) => {
    const m = mk(kind, reason, ts, { args: texts })
    return { ...m, cwd }
  }
  const cluster = (c: string) => f.short.has(c)

  switch (sub) {
    case 'clean':
      if (f.long.has('dry-run') || cluster('n') || cluster('i') || f.long.has('interactive')) return undefined
      return cluster('f') || f.long.has('force') ? [make('git-clean', 'git clean -f deletes untracked files: not recoverable')] : undefined
    case 'reset':
      return f.long.has('hard') ? [make('git-reset', 'git reset --hard discards uncommitted changes and moves the branch')] : undefined
    case 'checkout': {
      const afterDashes = texts.includes('--') ? texts.slice(texts.indexOf('--') + 1) : []
      const broad = afterDashes.some(x => BROAD.test(x)) || (afterDashes.length === 0 && f.operands.length === 1 && BROAD.test(f.operands[0]!.text))
      if (broad || cluster('f') || f.long.has('force'))
        return [make('git-discard', 'git checkout discards uncommitted changes to tracked files')]
      return undefined
    }
    case 'restore': {
      const staged = f.long.has('staged') || cluster('S')
      const worktree = !staged || cluster('W') || f.long.has('worktree')
      return worktree && f.operands.some(o => BROAD.test(o.text))
        ? [make('git-discard', 'git restore discards uncommitted changes to tracked files')] : undefined
    }
    case 'push': return pushRule(f, make)
    case 'branch': {
      const del = cluster('D') || ((cluster('d') || f.long.has('delete')) && (cluster('f') || f.long.has('force')))
      return del ? [make('git-branch', 'git branch -D deletes a branch even if unmerged')] : undefined
    }
    case 'stash': {
      const op = f.operands[0]?.text
      return op === 'drop' || op === 'clear' ? [make('git-stash', `git stash ${op} deletes stashed work`)] : undefined
    }
    default: return undefined
  }
}

function pushRule(f: Flags, make: (k: Kind, r: string, t?: Word[]) => Finding): Finding[] | undefined {
  const refspecs = f.operands.slice(1).map(o => o.text)
  const force = f.long.has('force') || f.long.has('force-with-lease') || f.short.has('f') || refspecs.some(r => r.startsWith('+'))
  const del = f.long.has('delete') || f.short.has('d') || refspecs.some(r => r.startsWith(':')) || f.long.has('mirror')
  if (!force && !del) return undefined
  return [make('git-push', del && !force ? 'git push --delete removes remote branches or tags' : 'a forced git push can overwrite commits on the remote')]
}

function sqlRule(h: Here, mk: Mk): Finding | undefined {
  const text = h.sqlText ?? ''
  const bad = destructiveSql(text)
  return bad.length ? mk('sql', `destructive SQL: ${bad.join('; ')}`, [], { args: bad }) : undefined
}

/** Statements in `sql` that drop, truncate, or delete without WHERE. Exported for tests. */
export function destructiveSql(sql: string): string[] {
  const found: string[] = []
  for (const stmt of sql.split(';')) {
    const s = stmt.replace(/--.*$/gm, ' ').replace(/\s+/g, ' ').trim()
    const m = /\b(DROP\s+\w+(\s+IF\s+EXISTS)?\s+\S+|TRUNCATE(\s+TABLE)?\s+\S+|DELETE\s+FROM\s+\S+)/i.exec(s)
    if (!m) continue
    if (/^DELETE\b/i.test(m[1]!) && /\bWHERE\b/i.test(s)) continue
    found.push(m[1]!.slice(0, 60))
  }
  return found
}

// R -e / Rscript -e: unlink(recursive=TRUE), file.remove, fs::dir_delete, system("rm ...")
function rRule(h: Here, mk: Mk): Finding[] | undefined {
  const a = h.u.args
  const code = a.flatMap((w, k) => (w.text === '-e' || w.text === '--expr' ? [a[k + 1]?.text ?? ''] : w.text.startsWith('--expr=') ? [w.text.slice(7)] : [])).join('\n')
  if (!code) return undefined
  const out: Finding[] = []
  for (const m of code.matchAll(/\b(system2?|shell)\s*\(\s*("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')/g))
    scan(m[2]!.slice(1, -1), { ...h.st }, h, h.depth + 1)
  // Only a literal first argument (or c("a", "b")) can be named; anything computed is "could not measure".
  const calls = [...code.matchAll(/\b(?:unlink|file\.remove|dir_delete|file_delete)\s*\(\s*(?:c\(([^)]*)\)|("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'))/g)]
  const risky = /\bunlink\s*\(.*recursive\s*=\s*(TRUE|T)\b/s.test(code) || /\b(file\.remove|dir_delete|file_delete)\s*\(/.test(code)
  if (!risky) return out.length ? out : undefined
  const lits = calls.flatMap(m => [...(m[1] ?? m[2]!).matchAll(/"((?:[^"\\]|\\.)*)"|'((?:[^'\\]|\\.)*)'/g)].map(l => l[1] ?? l[2] ?? ''))
  const words: Word[] = lits.map(text => ({ text, glob: /[*?]/.test(text), dynamic: false, tilde: text.startsWith('~'), subs: [] }))
  out.push(mk('r', 'R code deletes files or directories (unlink / file.remove / dir_delete)', words, { args: [] }))
  return out
}

// ---- last-resort regex ------------------------------------------------------------------

/**
 * Trivially safe fallback for when the classifier itself throws: coarse on purpose,
 * it only has to say "this text looks destructive" so the hook can fail closed.
 */
export const FALLBACK_RISKY = new RegExp(
  [
    String.raw`\brm\s+(-\w*[rRf]|--(recursive|force))`,
    String.raw`\bfind\b.*(-delete|-exec\s+\S*rm\b)`,
    String.raw`\bgit\b.*\b(clean\s+-\w*f|reset\s+--hard|push\b.*(--force|--delete|\s-\w*f|\s\+)|branch\s+-D|stash\s+(drop|clear)|checkout\s+(--\s+)?\.|restore\s+\.)`,
    String.raw`\b(truncate|shred|mkfs\S*|newfs\S*)\b`, String.raw`\bdd\b.*\bof=`,
    String.raw`\b(chmod|chown|chgrp)\s+-\w*R`, String.raw`\bcargo\s+clean\b`,
    String.raw`\b(DROP\s+\w+|TRUNCATE|DELETE\s+FROM)\b`, String.raw`\bunlink\s*\(`,
    String.raw`(^|[^>&0-9])>\s*(?!\/dev\/)[^&>\s]`,
  ].join('|'), 'i',
)

files.hooks/config.ts:
import type { PluginOptions } from 'claude-code'

import { FALLBACK_RISKY } from './classify'

export type AskFrom = 'low' | 'medium' | 'high'
/** The runtime choice: the three `askFrom` bars plus `off` (never ask). */
export type Level = AskFrom | 'off'
export const LEVELS: readonly Level[] = ['off', 'low', 'medium', 'high']

/** One line per level, for `/command-guard` with no argument. */
export const LEVEL_MEANING: Record<Level, string> = {
  off: 'never ask',
  low: 'ask for everything, even low risk',
  medium: 'ask from medium risk up',
  high: 'ask only for high risk',
}

/** A stored or typed word as a level, or undefined when it is none. */
export const asLevel = (v: unknown): Level | undefined => {
  const t = typeof v === 'string' ? v.trim().toLowerCase() : ''
  return (LEVELS as readonly string[]).includes(t) ? (t as Level) : undefined
}
export type BlastConfig = { maxListed: number; extraPatterns: RegExp[]; badPatterns: string[]; askFrom: AskFrom }

/** Rank of a risk level for the `askFrom` bar. Unknown (not checked) ranks with high: it is never skipped. */
export const RANK = { low: 0, medium: 1, high: 2, unknown: 2 } as const

/** True when nothing needs a dialog: every part is below the `askFrom` bar and none went unchecked (`unlisted`). */
export const isBelowBar = (levels: ('low' | 'medium' | 'high' | 'unknown')[], unlisted: number, askFrom: AskFrom): boolean =>
  unlisted === 0 && levels.every(l => RANK[l] < RANK[askFrom])

/** Options from plugin.json userConfig. A pattern that is not a valid regex is reported, never silently dropped. */
export function readConfig(options: PluginOptions): BlastConfig {
  const n = Number(options.maxListed)
  const maxListed = Number.isFinite(n) ? Math.min(200, Math.max(5, Math.round(n))) : 5
  const raw = Array.isArray(options.extraPatterns) ? (options.extraPatterns as string[]) : []
  const extraPatterns: RegExp[] = []
  const badPatterns: string[] = []
  for (const p of raw) {
    try {
      extraPatterns.push(new RegExp(p))
    } catch {
      badPatterns.push(p)
    }
  }
  const askFrom: AskFrom = options.askFrom === 'low' || options.askFrom === 'high' ? options.askFrom : 'medium'
  return { maxListed, extraPatterns, badPatterns, askFrom }
}

/**
 * The fail-closed rule, as a pure function: when the classifier, the measurer or the dialog
 * code throws, refuse only a command whose text looks destructive to the coarse fallback
 * regex (or to one of the user's own patterns). Returns the refusal, or undefined to let it run.
 */
export function failClosedReason(command: unknown, cfg: BlastConfig): string | undefined {
  const text = typeof command === 'string' ? command : ''
  const risky = FALLBACK_RISKY.test(text) || cfg.extraPatterns.some(re => re.test(text))
  return risky
    ? `Blocked by command-guard: could not analyse this command and it looks destructive. Not run: ${text.replace(/\s+/g, ' ').trim().slice(0, 200)}. Ask the user to confirm, then retry.`
    : undefined
}

files.hooks/format.ts:
// Text for the dialog, the refusal the model reads and the toast. Plain text only: the dialog is the
// engine's own question dialog, which draws the same on every surface. Layout, top to bottom:
//   a one-line headline ("High risk · deletes data/"), the command, a few "Label   value" rows
//   (one honesty note at most), then the question. Nothing here contains ALL-CAPS words.
import type { Finding } from './classify'
import type { Row } from './folder'
import type { Report } from './measure'
import { PUSHED_NOTE } from './recover'
import type { RiskLevel } from './recover'

const clip = (s: string, n: number) => (s.length > n ? s.slice(0, n - 1) + '…' : s)
const oneLine = (s: string) => s.replace(/\s+/g, ' ').trim()
// first letter up, unless the text starts with a command name ("git diff failed")
const cap1 = (s: string) => (/^(git|rm|cp|mv|chmod|chown|find|du|dd|cargo|psql|mysql|sqlite3)\b/.test(s) ? s : s.charAt(0).toUpperCase() + s.slice(1))

const LABEL_WIDTH = 13
const DEFAULT_ROWS = 5 // rows shown under a list heading; the rest is "+N more"
const MAX_NOTES = 2
const FOOTNOTE = 'Estimated from file names and your last fetch.'
// The dialog takes plain text only, so the level is coloured with a dot. Unknown counts as red: it was not checked.
const WORD: Record<RiskLevel, string> = { high: '🔴 High', medium: '🟠 Medium', low: '🟢 Low', unknown: '🔴 Unknown' }
const WORST_FIRST: RiskLevel[] = ['high', 'unknown', 'medium', 'low']

const row = (label: string, value: string) => `${label.padEnd(LABEL_WIDTH)}${value}`
const levelOf = (r: Report): RiskLevel => r.risk?.level ?? 'unknown'
const worst = (reports: Report[]): RiskLevel => WORST_FIRST.find(l => reports.some(r => levelOf(r) === l)) ?? 'unknown'

// What the command does, when the measurer could not say.
function fallbackAction(f: Finding): string {
  const names = f.targets.map(t => t.raw)
  const what = (none: string) => (names.length === 1 ? clip(names[0]!, 50) : names.length > 1 ? `${names.length} paths` : none)
  switch (f.kind) {
    case 'rm': return `deletes ${f.viaXargs ? 'the files it is given' : what('files')}`
    case 'r': return 'deletes files from R code'
    case 'truncate': return `empties ${what('files')}`
    case 'shred': return `shreds ${what('files')}`
    case 'chmod': return `changes permissions of ${what('a tree')}`
    case 'cargo-clean': return 'deletes target/'
    case 'redirect': case 'overwrite': return `overwrites ${what('files')}`
    case 'dd': return 'overwrites data'
    case 'mkfs': return 'erases a disk'
    case 'find': return 'deletes every match'
    case 'git-clean': return 'deletes untracked files'
    case 'git-reset': case 'git-discard': return 'discards uncommitted changes'
    case 'git-push': return 'overwrites remote history'
    case 'git-branch': return 'deletes a branch'
    case 'git-stash': return 'deletes stashed work'
    case 'sql': return 'runs destructive SQL'
    case 'custom': return 'matches your extra pattern'
    case 'opaque': return clip(f.reason, 70)
  }
}
const actionOf = (r: Report) => r.action ?? fallbackAction(r.finding)

function list(title: string, rows: string[], more: number, max: number): string[] {
  if (rows.length === 0) return []
  const shown = rows.slice(0, max)
  const left = more + rows.length - shown.length
  return [title, ...shown.map(x => `  ${clip(x, 110)}`), ...(left > 0 ? [`  +${left} more`] : [])]
}

function folderRows(rows: Row[], indent = ''): string[] {
  return rows.map(([k, v]) => indent + row(k, clip(v, 200)))
}

function details(r: Report, sessionCwd: string | undefined, max: number): string[] {
  const f = r.finding
  const folders = r.folders ?? []
  const out: string[] = []
  if (f.cwd && f.cwd !== sessionCwd) out.push(row('Runs in', f.cwd))
  if (folders.length === 1) out.push(...folderRows(folders[0]!.rows))
  else
    for (const fr of folders) out.push(fr.title, ...folderRows(fr.rows, '  '))
  if (folders.length === 0 && r.risk?.headline) out.push(row('Impact', clip(cap1(r.risk.headline), 160)))
  for (const g of r.riskGroups ?? []) if (!g.subset && !(g.extra && folders.length > 0)) out.push(...list(g.title, g.rows, g.more, max))
  // a scanned folder already has its name in the headline and its size in the rows above
  const scanned = folders.length === 1 && folders[0]!.rows.some(([k]) => k === 'Size')
  r.groups.forEach((g, k) => {
    if (k === 0 && scanned && g.rows.length <= 1 && g.more === 0) return
    if (g.extra && scanned) return
    out.push(...list(g.title, g.rows, g.more, max))
  })
  if (folders.length === 0 && r.summary.length && r.items !== 1) out.push(row('Total', r.summary.join('; ')))
  const notes = r.notes.filter(n => !(folders.length > 0 && n === PUSHED_NOTE)).slice(0, MAX_NOTES)
  for (const n of notes) out.push(row('Note', clip(cap1(n), 120)))
  if (r.unmeasured && r.unmeasured !== 'native Windows') out.push(row('Not checked', clip(cap1(r.unmeasured), 120)))
  return out
}

/** The question shown in the dialog. Ends in a question mark, as the dialog wants. */
export function dialogText(command: string, reports: Report[], unlisted: number, sessionCwd?: string, maxRows = DEFAULT_ROWS): string {
  const many = reports.length > 1
  const lines: string[] = []
  if (many) lines.push(`${WORD[worst(reports)]} risk · ${reports.length + unlisted} risky commands`, '')
  else lines.push(`${WORD[worst(reports)]} risk · ${reports[0] ? clip(actionOf(reports[0]), 90) : 'risky command'}`, clip(oneLine(command), 200), '')
  reports.forEach(r => {
    if (many) lines.push(`${WORD[levelOf(r)]} · ${clip(actionOf(r), 80)}`, `  ${clip(oneLine(r.finding.command || r.finding.kind), 120)}`)
    const d = details(r, sessionCwd, maxRows)
    lines.push(...(many ? d.map(x => `  ${x}`) : d), '')
  })
  if (unlisted > 0) lines.push(`+${unlisted} more risky ${unlisted === 1 ? 'command' : 'commands'}, not checked`, '')
  // the closing question is never clipped away: the dialog wants the text to end in a question mark
  const footer = [...(reports.some(r => (r.folders ?? []).length > 0) ? [FOOTNOTE, ''] : []), 'Run this command?']
  const body = lines.join('\n')
  return clip(body, 6000 - footer.join('\n').length - 1) + '\n' + footer.join('\n')
}

/** One line per fact, short: what the model reads after a refusal. */
export function summaryLines(reports: Report[], maxRows = 6): string[] {
  const out: string[] = []
  for (const r of reports) {
    out.push(`${WORD[levelOf(r)]} risk · ${actionOf(r)}${r.finding.cwd ? ` (in ${r.finding.cwd})` : ''}`)
    const folders = r.folders ?? []
    if (folders.length === 0 && r.risk?.headline) out.push(`  Impact: ${clip(r.risk.headline, 220)}`)
    for (const fr of folders) out.push(`  ${clip(fr.title, 120)} · Recoverable: ${clip(fr.rows.at(-1)?.[1] ?? '', 200)}`)
    let left = maxRows
    for (const g of r.groups)
      for (const x of g.rows.slice(0, left)) (out.push(`  ${clip(x, 120)}`), left--)
    if (r.items !== 1) out.push(...r.summary.map(s => `  Total: ${s}`))
    if (r.unmeasured) out.push(`  Not checked: ${clip(r.unmeasured, 120)}`)
  }
  return out
}

export function denyText(why: string, command: string, reports: Report[]): string {
  return clip(
    [
      `Blocked by command-guard (${why}). Not run: ${clip(oneLine(command), 200)}`,
      ...summaryLines(reports),
      'Ask the user before retrying, or use a narrower, reversible command.',
    ].join('\n'), 2500,
  )
}

/** One line (no line breaks): shown as a toast and in the status line. */
export function toastText(reports: Report[]): string {
  const total = reports.flatMap(r => r.summary)[0]?.replace(/^1 item, /, '')
  return oneLine(`Blocked ${clip(oneLine(reports[0]?.finding.command ?? 'command'), 60)}${total ? ` · ${total}` : ''}`)
}

files.hooks/measure.ts:
// The measurer: READ-ONLY look at what a classified command would hit. Every probe
// is an argv run through `run` (= $.process.run, no shell), so nothing the model
// wrote is ever evaluated. The one place user text reaches an argv is a path or a ref,
// and those are absolute paths or validated against REF before use.
//
// Contract: `measure` never throws and never says "fine". When a probe fails it sets
// `unmeasured` and the caller holds the command anyway (fail closed on measuring).
import type { Finding, Target } from './classify'
import { normalize } from './classify'
import { assessFolders } from './folder'
import type { FolderRisk, Known, Mode } from './folder'
import { assessLoss } from './recover'
import type { Risk } from './recover'

export type RunResult = { exitCode: number; stdout: string; stderr: string; isStdoutTruncated?: boolean }
export type Run = (argv: readonly string[], cwd?: string, opts?: { timeoutMs?: number }) => Promise<RunResult>
// home and cwd are only for the folder-risk wording (CRITICAL: home, working directory, its parents); both optional
export type Config = { maxListed: number; home?: string; cwd?: string }

// subset: the rows only repeat names the plain listing shows; extra: left out of the dialog when a folder summary is shown
export type Group = { title: string; rows: string[]; more: number; subset?: boolean; extra?: boolean }
export type Report = {
  finding: Finding
  groups: Group[]
  risk?: Risk // what could not be got back: uncommitted, untracked, unpushed, outside git
  riskGroups?: Group[] // the rows behind `risk`, shown BEFORE the plain listing
  folders?: FolderRisk[] // per directory: what it is, what is in it, what could be got back
  summary: string[] // totals
  action?: string // what the command does, lower case, for the headline: "deletes data/"
  items?: number // how many existing targets a path command names
  notes: string[] // caveats that do not stop the hold
  unmeasured?: string // set when the blast radius could not be established
  skip?: boolean // a conditional finding whose condition is false: nothing to hold
}

// ---- formatting and parsing (pure, exported for tests) --------------------------------

export const fmtInt = (n: number) => n.toLocaleString('en-US')
export function fmtBytes(bytes: number): string {
  const u = ['B', 'KB', 'MB', 'GB', 'TB']
  let v = bytes
  let k = 0
  while (v >= 1024 && k < u.length - 1) (v /= 1024, k++)
  return `${k === 0 ? v : +v.toFixed(v >= 10 ? 0 : 1)} ${u[k]}`
}
export const fmtKb = (kb: number) => fmtBytes(kb * 1024)
const cap1 = (s: string) => s.charAt(0).toUpperCase() + s.slice(1)
const lines = (s: string) => s.split('\n').map(l => l.replace(/\r$/, '')).filter(l => l !== '')
const plural = (n: number, w: string, many = w + 's') => `${fmtInt(n)} ${n === 1 ? w : many}`

/** `du -sk` output: "<kb>\t<path>" per line. */
export function parseDu(out: string): Map<string, number> {
  const m = new Map<string, number>()
  for (const l of lines(out)) {
    const hit = /^(\d+)\s+(.*)$/.exec(l)
    if (hit) m.set(hit[2]!, Number(hit[1]))
  }
  return m
}

/** `git diff --name-status` output to display rows ("M  path", "R  old -> new"). */
export function parseNameStatus(out: string): string[] {
  return lines(out).map(l => {
    const [st, ...paths] = l.split('\t')
    return `${(st ?? '?').slice(0, 1)}  ${paths.join(' -> ')}`
  })
}

/** `git clean -n` output: "Would remove <path>" per line. */
export function parseCleanDryRun(out: string): string[] {
  return lines(out).flatMap(l => {
    const m = /^Would (?:remove|skip repository) (.*)$/.exec(l)
    return m ? [m[1]!.replace(/\/$/, '')] : []
  })
}

const cap = (title: string, rows: string[], max: number, flags: { subset?: boolean; extra?: boolean } = {}): Group => ({
  title, rows: rows.slice(0, max), more: Math.max(0, rows.length - max), ...flags,
})

function short(path: string, cwd?: string): string {
  if (cwd && path.startsWith(cwd + '/')) return path.slice(cwd.length + 1)
  return path
}

const REF = /^[A-Za-z0-9_@][A-Za-z0-9_.\-/@{}^~]*$/ // never starts with "-": a ref cannot become an option
const chunks = <T>(a: T[], n: number) => Array.from({ length: Math.ceil(a.length / n) }, (_, k) => a.slice(k * n, (k + 1) * n))

// ---- probes on paths ------------------------------------------------------------------

const empty = (): Omit<Report, 'finding'> => ({ groups: [], summary: [], notes: [] })

async function duMany(run: Run, paths: string[]): Promise<Map<string, number>> {
  const all = new Map<string, number>()
  for (const part of chunks(paths, 60))
    for (const [p, kb] of parseDu((await run(['du', '-sk', ...part])).stdout)) all.set(p, kb)
  return all
}

async function present(run: Run, paths: string[], extra: string[] = []): Promise<Set<string>> {
  const found = new Set<string>()
  for (const part of chunks(paths, 60))
    for (const l of lines((await run(['find', ...part, '-maxdepth', '0', ...extra, '-print'])).stdout)) found.add(l)
  return found
}

/** Expand a glob target with `find -path` at exactly the glob's depth (no shell involved). */
export async function expandGlob(run: Run, t: Target): Promise<string[]> {
  const parts = t.path!.split('/').filter(Boolean)
  const g = parts.findIndex(p => /[*?[]/.test(p))
  const baseParts = parts.slice(0, g)
  const rest = parts.slice(g)
  const base = '/' + baseParts.join('/')
  const esc = (s: string) => s.replace(/[\\*?[]/g, c => '\\' + c)
  const pattern = `${base === '/' ? '' : esc(base)}/${rest.join('/')}`
  const res = await run(['find', base, '-mindepth', String(rest.length), '-maxdepth', String(rest.length), '-path', pattern])
  return lines(res.stdout).filter(p => {
    // Shell globs skip dot-files unless the pattern component itself starts with a dot.
    const comps = p.split('/').filter(Boolean).slice(baseParts.length)
    return comps.every((c, k) => !c.startsWith('.') || (rest[k] ?? '').startsWith('.'))
  })
}

// folders: how the command treats a directory (default: it deletes it); false: no folder assessment
const VERBS: Record<string, [string, string]> = { // verb -> [headline form, list title]
  delete: ['deletes', 'Deletes'], empty: ['empties', 'Empties'], 'overwrite and destroy': ['shreds', 'Shreds'],
  'change recursively': ['changes permissions of', 'Changes'], 'delete (untracked)': ['deletes', 'Deletes untracked'],
  overwrite: ['overwrites', 'Overwrites'], 'overwrite or merge into': ['overwrites', 'Overwrites or merges into'],
}
type PathOpts = { verb: string; expandSingleDir: boolean; cap: number; risk?: boolean; folders?: Mode | false; canLower?: boolean }

// Rows for a set of targets: kind, size, file count; for one directory also its biggest children.
async function describePaths(run: Run, f: Finding, targets: Target[], o: PathOpts, cfg: Config): Promise<Omit<Report, 'finding'>> {
  const r = empty()
  const paths: string[] = []
  for (const t of targets) {
    if (!t.path) r.notes.push(`could not resolve ${t.raw}: ${t.unresolved}`)
    else if (t.glob) {
      const hits = await expandGlob(run, t)
      if (hits.length === 0) r.notes.push(`${t.raw} matches nothing right now`)
      paths.push(...hits)
    } else paths.push(t.path)
  }
  const uniq = [...new Set(paths)].slice(0, o.cap)
  if (paths.length > uniq.length) r.notes.push(`checked the first ${fmtInt(uniq.length)} of ${fmtInt(paths.length)} paths`)
  if (uniq.length === 0) return r

  const exists = await present(run, uniq)
  const live = uniq.filter(p => exists.has(p))
  const dirs = await present(run, live, ['-type', 'd'])
  const sizes = await duMany(run, live)
  const counts = await countFiles(run, [...dirs], r)
  const links = o.folders === false ? new Set<string>() : await linksAmong(run, live, dirs)
  const truncated = r.notes.some(n => n.startsWith('file counts are lower bounds'))
  const rows = uniq.map(p => {
    if (!exists.has(p)) return `${short(p, f.cwd)} · does not exist`
    const kb = sizes.get(p)
    const bits: string[] = links.has(p) ? ['symlink'] : []
    if (counts?.has(p)) bits.push(plural(counts.get(p)!, 'file'))
    if (kb !== undefined) bits.push(fmtKb(kb))
    return `${short(p, f.cwd)}${dirs.has(p) ? '/' : ''}${bits.length ? ` · ${bits.join(', ')}` : ''}`
  })
  const [verbForm, title] = VERBS[o.verb] ?? [o.verb + 's', cap1(o.verb)]
  r.groups.push(cap(title, rows, cfg.maxListed))
  r.items = live.length
  if (live.length === 1) r.action = `${verbForm} ${short(live[0]!, f.cwd)}${dirs.has(live[0]!) ? '/' : ''}`
  else if (live.length > 1) r.action = `${verbForm} ${plural(live.length, dirs.size === live.length ? 'folder' : dirs.size === 0 ? 'file' : 'item')}`
  const totalKb = [...sizes.values()].reduce((a, b) => a + b, 0)
  const totalFiles = counts && dirs.size > 0 ? [...counts.values()].reduce((a, b) => a + b, 0) : undefined
  r.summary.push(
    live.length === 0
      ? 'nothing exists at that path right now'
      : [plural(live.length, 'item'), totalFiles !== undefined ? plural(totalFiles, 'file') : undefined, fmtKb(totalKb)]
          .filter(Boolean).join(', '),
  )
  if (o.expandSingleDir && live.length === 1 && dirs.has(live[0]!)) await children(run, live[0]!, f, r, cfg)
  // removing a symlink removes only the link: it is not "a file outside git" whose content is lost
  const atRisk = o.folders === 'delete' || o.folders === undefined ? live.filter(p => !links.has(p)) : live
  if (o.risk !== false && atRisk.length > 0) await addRisk(run, atRisk, r, cfg)
  if (o.folders !== false && live.length > 0) {
    const known = new Map<string, Known>([...dirs].map(d => [d, { kb: sizes.get(d), files: counts?.get(d), filesLowerBound: truncated }]))
    await addFolders(run, f, r, live, dirs, links, { mode: o.folders ?? 'delete', canLower: o.canLower !== false, known }, cfg)
  }
  return r
}

// Symbolic links among the paths (find -type l does not follow them). Best effort: a failed probe means "none seen".
async function linksAmong(run: Run, live: string[], dirs: Set<string>): Promise<Set<string>> {
  try {
    return await present(run, live.filter(p => !dirs.has(p)), ['-type', 'l'])
  } catch {
    return new Set()
  }
}

// Folder risk for the directories (and symlinks) among the targets, merged into the overall RISK line. An add-on to the
// listing: if it fails the listing and the file-level risk stand, and a note says so.
async function addFolders(
  run: Run, f: Finding, r: Omit<Report, 'finding'>, live: string[], dirs: Set<string> | undefined, linkSet: Set<string> | undefined,
  o: { mode: Mode; canLower: boolean; known?: Map<string, Known> }, cfg: Config,
): Promise<void> {
  try {
    const dirSet = dirs ?? (await present(run, live, ['-type', 'd']))
    const links = linkSet ?? (await present(run, live.filter(p => !dirSet.has(p)), ['-type', 'l']))
    const cands = [...dirSet, ...links]
    if (cands.length === 0) return
    const res = await assessFolders(run, cands, { home: cfg.home, cwd: cfg.cwd, runCwd: f.cwd, mode: o.mode, known: o.known })
    r.folders = res.folders
    if (res.skipped > 0) r.notes.push(`folder details for ${res.folders.length} of ${res.folders.length + res.skipped} folders`)
    mergeFolderRisk(r, res.folders, o.canLower && res.skipped === 0 && cands.length === live.length)
  } catch (err) {
    r.notes.push(`folder details unavailable: ${(err as Error).message || 'probe failed'}`)
  }
}

const LEVEL_RANK: Record<string, number> = { low: 0, medium: 1, high: 3 }

/** The folder verdict can raise the overall level; it can lower MEDIUM to LOW only when it saw every target completely. */
function mergeFolderRisk(r: Omit<Report, 'finding'>, folders: FolderRisk[], mayLower: boolean): void {
  const worst = folders.reduce((a, b) => ((LEVEL_RANK[b.level] ?? -1) > (LEVEL_RANK[a.level] ?? -1) ? b : a))
  const cur = r.risk
  if (!cur) {
    r.risk = { level: worst.level, headline: worst.headline }
    return
  }
  if ((worst.level === 'high' && cur.level !== 'high') || (worst.level === 'medium' && cur.level === 'low'))
    r.risk = { level: worst.level, headline: [worst.headline, cur.headline].filter(Boolean).join('; ') }
  else if (mayLower && cur.level === 'medium' && folders.every(x => x.level === 'low' && x.complete))
    r.risk = { level: 'low', headline: worst.headline }
  // a plain folder holding nothing but safe repositories is "outside any repository" to the file-level check
  else if (mayLower && cur.level === 'high' && folders.every(x => x.level === 'low' && x.complete && x.onlyRepos))
    r.risk = { level: 'low', headline: worst.headline }
}

// Attach the data-loss assessment. assessLoss never throws; a failed probe yields level 'unknown'.
async function addRisk(run: Run, live: string[], r: Omit<Report, 'finding'>, cfg: Config): Promise<void> {
  const a = await assessLoss(run, live, cfg)
  r.risk = a.risk
  r.riskGroups = a.groups
  r.notes.push(...a.notes)
}

// One find over all dirs: every non-directory under them, attributed to its dir by prefix.
async function countFiles(run: Run, dirs: string[], r: Omit<Report, 'finding'>): Promise<Map<string, number> | undefined> {
  if (dirs.length === 0) return new Map()
  try {
    const res = await run(['find', ...dirs, '!', '-type', 'd', '-print'])
    const counts = new Map<string, number>(dirs.map(d => [d, 0]))
    for (const l of lines(res.stdout)) for (const d of dirs) if (l.startsWith(d + '/')) counts.set(d, counts.get(d)! + 1)
    if (res.isStdoutTruncated) r.notes.push('file counts are lower bounds (listing truncated)')
    return counts
  } catch (err) {
    r.notes.push(`file count unavailable: ${(err as Error).message}`)
    return undefined
  }
}

async function children(run: Run, dir: string, f: Finding, r: Omit<Report, 'finding'>, cfg: Config): Promise<void> {
  try {
    const kids = lines((await run(['find', dir, '-mindepth', '1', '-maxdepth', '1'])).stdout).slice(0, 500)
    const dirs = await present(run, kids, ['-type', 'd'])
    const sizes = await duMany(run, kids)
    const rows = kids
      .map(k => ({ k, kb: sizes.get(k) ?? 0 }))
      .sort((a, b) => b.kb - a.kb)
      .map(({ k, kb }) => `${short(k, dir)}${dirs.has(k) ? '/' : ''} · ${fmtKb(kb)}`)
    if (rows.length) r.groups.push(cap(`Largest inside ${short(dir, f.cwd)}/`, rows, cfg.maxListed, { extra: true }))
  } catch (err) {
    r.notes.push(`could not list the contents: ${(err as Error).message}`)
  }
}

// ---- per-kind measurement ---------------------------------------------------------------

const pos = (args: string[]) => {
  const dd = args.indexOf('--')
  return (dd < 0 ? args : args.slice(0, dd)).filter(a => !a.startsWith('-')).concat(dd < 0 ? [] : args.slice(dd + 1))
}

async function git(run: Run, cwd: string | undefined, ...argv: string[]): Promise<string> {
  const res = await run(['git', '--no-optional-locks', '--no-pager', ...argv], cwd)
  if (res.exitCode !== 0) throw new Error(`git ${argv[0]} failed: ${res.stderr.trim().split('\n')[0] || `exit ${res.exitCode}`}`)
  return res.stdout
}

export async function measure(run: Run, f: Finding, cfg: Config): Promise<Report> {
  try {
    return { finding: f, ...(await dispatch(run, f, cfg)) }
  } catch (err) {
    return { finding: f, groups: [], summary: [], notes: [], unmeasured: (err as Error).message || 'probe failed' }
  }
}

async function dispatch(run: Run, f: Finding, cfg: Config): Promise<Omit<Report, 'finding'>> {
  const dp = (verb: string, targets = f.targets, expandSingleDir = true) =>
    describePaths(run, f, targets, { verb, expandSingleDir, cap: 500 }, cfg)
  switch (f.kind) {
    case 'rm': {
      if (f.viaXargs || f.targets.length === 0)
        return { ...empty(), unmeasured: 'the paths arrive on stdin (xargs) or are not named' }
      return dp('delete')
    }
    case 'truncate': return dp('empty', f.targets, false)
    case 'shred': return dp('overwrite and destroy', f.targets, false)
    case 'chmod': return describePaths(run, f, f.targets, { verb: 'change recursively', expandSingleDir: true, cap: 500, risk: false, folders: 'modify' }, cfg)
    case 'r': {
      const r = await dp('delete')
      if (f.targets.length === 0) r.notes.push('the paths in the R code are computed: could not name them')
      return r
    }
    case 'cargo-clean': return cargoClean(run, f, cfg)
    case 'redirect': return redirect(run, f, cfg)
    case 'overwrite': return overwrite(run, f, cfg)
    case 'dd': return dd(run, f, cfg)
    case 'mkfs': return { ...empty(), unmeasured: 'a device is erased; its contents are not inspected' }
    case 'find': return findRule(run, f, cfg)
    case 'git-clean': return gitClean(run, f, cfg)
    case 'git-reset': return gitReset(run, f, cfg)
    case 'git-discard': return gitDiscard(run, f, cfg)
    case 'git-push': return gitPush(run, f, cfg)
    case 'git-branch': return gitBranch(run, f, cfg)
    case 'git-stash': return gitStash(run, f, cfg)
    case 'sql': return { ...empty(), groups: [{ title: 'Statements', rows: f.args, more: 0 }], unmeasured: 'database contents are not inspected' }
    case 'custom': return { ...empty(), action: 'matches your extra pattern', unmeasured: 'nothing measured for your extra patterns' }
    case 'opaque': return { ...empty(), unmeasured: f.reason }
  }
}

async function cargoClean(run: Run, f: Finding, cfg: Config) {
  const a = f.args
  const flag = (n: string) => { const k = a.indexOf(n); return k >= 0 ? a[k + 1] : a.find(x => x.startsWith(n + '='))?.slice(n.length + 1) }
  const dir = flag('--target-dir')
  const manifest = flag('--manifest-path')
  const abs = (p: string) => (p.startsWith('/') ? normalize(p) : f.cwd ? normalize(`${f.cwd}/${p}`) : undefined)
  const where = dir ? abs(dir) : manifest ? abs(manifest.replace(/[^/]*$/, '') + 'target') : f.cwd ? `${f.cwd}/target` : undefined
  if (!where) return { ...empty(), unmeasured: 'the working directory is not known' }
  const r = await describePaths(run, f, [{ raw: where, path: where, glob: false }], { verb: 'delete', expandSingleDir: true, cap: 1, risk: false }, cfg)
  r.notes.push('cargo may clean the workspace\'s target/ or CARGO_TARGET_DIR instead')
  return r
}

async function redirect(run: Run, f: Finding, cfg: Config) {
  const p = f.targets[0]!.path!
  // find -L <p> -maxdepth 0 -type f -size +0c : prints p only for a non-empty regular file.
  const hit = lines((await run(['find', '-L', p, '-maxdepth', '0', '-type', 'f', '-size', '+0c', '-print'])).stdout)
  if (hit.length === 0) return { ...empty(), skip: true }
  return describePaths(run, f, f.targets, { verb: 'overwrite', expandSingleDir: false, cap: 1 }, cfg)
}

async function overwrite(run: Run, f: Finding, cfg: Config) {
  const dest = f.targets[0]!.path!
  const cands = [dest, ...f.args.map(s => `${dest}/${s.slice(s.lastIndexOf('/') + 1)}`)]
  const hits = [...(await present(run, cands, ['-type', 'f']))]
  if (hits.length === 0) {
    const dirs = await overwrittenDirs(run, f, dest)
    if (dirs.length === 0) return { ...empty(), skip: true }
    const targets = dirs.map(p => ({ raw: p, path: p, glob: false }))
    return describePaths(run, f, targets, { verb: 'overwrite or merge into', expandSingleDir: false, cap: 100, folders: 'overwrite', canLower: false }, cfg)
  }
  const targets = hits.map(p => ({ raw: p, path: p, glob: false }))
  return describePaths(run, f, targets, { verb: 'overwrite', expandSingleDir: false, cap: 100 }, cfg)
}

// `cp -rf src dest` / `mv -f src dest` where dest is a folder that already holds a folder named like src: its files are replaced.
async function overwrittenDirs(run: Run, f: Finding, dest: string): Promise<string[]> {
  const abs = f.args.filter(a => !/[*?[$`~]/.test(a)).map(a => (a.startsWith('/') ? normalize(a) : f.cwd ? normalize(`${f.cwd}/${a}`) : '')).filter(Boolean)
  if (abs.length === 0 || (await present(run, [dest], ['-type', 'd'])).size === 0) return []
  const srcDirs = await present(run, abs, ['-type', 'd'])
  const inDest = [...srcDirs].map(p => `${dest}/${p.slice(p.lastIndexOf('/') + 1)}`)
  return inDest.length ? [...(await present(run, inDest, ['-type', 'd']))] : []
}

async function dd(run: Run, f: Finding, cfg: Config) {
  const t = f.targets[0]!
  if (t.path?.startsWith('/dev/'))
    return { ...empty(), action: `writes over ${t.path}`, notes: ['Everything on the device is overwritten'], unmeasured: 'device contents are not inspected' }
  return describePaths(run, f, f.targets, { verb: 'overwrite', expandSingleDir: false, cap: 1 }, cfg)
}

// find ... -delete / -exec rm  ->  the same find with the destructive part swapped for -print.
export function findPreviewArgs(args: string[]): { argv: string[]; note?: string } | undefined {
  const out: string[] = []
  let note: string | undefined
  for (let i = 0; i < args.length; i++) {
    const t = args[i]!
    if (/^-(fprint0?|fprintf|fls)$/.test(t)) return undefined // would write a file
    if (t === '-delete') out.push('-print')
    else if (/^-(exec|execdir|ok|okdir)$/.test(t)) {
      let j = i + 1
      while (j < args.length && args[j] !== ';' && args[j] !== '+') j++
      const cmd = (args[i + 1] ?? '').slice((args[i + 1] ?? '').lastIndexOf('/') + 1)
      if (/^(rm|unlink|shred|rmdir|sh|bash|zsh)$/.test(cmd)) out.push('-print')
      else note = 'an -exec filter was left out, so the list may include extra paths'
      i = j
    } else out.push(t)
  }
  return { argv: out, ...(note ? { note } : {}) }
}

async function findRule(run: Run, f: Finding, cfg: Config) {
  if (f.args.some(a => /[$`]/.test(a))) return { ...empty(), unmeasured: 'the find arguments contain shell expansions' }
  const prev = findPreviewArgs(f.args)
  if (!prev) return { ...empty(), unmeasured: 'the find writes files itself (-fprint/-fls): not previewed' }
  const res = await run(['find', ...prev.argv], f.cwd)
  const abs = (p: string) => (p.startsWith('/') ? p : f.cwd ? normalize(`${f.cwd}/${p}`) : p)
  const found = lines(res.stdout).map(abs)
  const r = empty()
  if (prev.note) r.notes.push(prev.note)
  if (res.exitCode !== 0 && found.length === 0) throw new Error(`find failed: ${res.stderr.trim().split('\n')[0] || `exit ${res.exitCode}`}`)
  if (res.isStdoutTruncated) r.notes.push('match list truncated: counts are lower bounds')
  const sized = found.slice(0, 300)
  const sizes = await duMany(run, sized)
  const rows = sized.map(p => `${short(p, f.cwd)}  ${fmtKb(sizes.get(p) ?? 0)}`).concat(found.slice(300).map(p => short(p, f.cwd)))
  r.groups.push(cap('Deletes', rows, cfg.maxListed))
  r.action = `deletes ${plural(found.length, 'match', 'matches')}`
  const kb = [...sizes.values()].reduce((a, b) => a + b, 0)
  r.summary.push(`${plural(found.length, 'match', 'matches')}, ${fmtKb(kb)}${found.length > sized.length ? ' (first 300 sized)' : ''}`)
  if (found.length > 0) await addRisk(run, found.slice(0, 500), r, cfg)
  if (found.length > 0) {
    // a match that is a directory is deleted with everything in it (find -delete only when it is empty by then)
    const matched = found.slice(0, 500)
    await addFolders(run, f, r, matched, undefined, undefined, { mode: 'delete', canLower: true }, cfg)
  }
  return r
}

// ---- git ------------------------------------------------------------------------------------

async function gitClean(run: Run, f: Finding, cfg: Config) {
  const a = f.args
  const letters = new Set(a.filter(x => /^-[^-]/.test(x)).flatMap(x => [...x.slice(1)]))
  const probe = ['clean', '-n', ...['d', 'x', 'X'].filter(l => letters.has(l)).map(l => '-' + l)]
  const paths: string[] = []
  let afterDashes = false
  for (let i = 0; i < a.length; i++) {
    const x = a[i]!
    if (afterDashes) paths.push(x)
    else if (x === '--') afterDashes = true
    else if (x === '-e' || x === '--exclude') probe.push('-e', a[++i] ?? '')
    else if (x.startsWith('--exclude=')) probe.push(x)
    else if (!x.startsWith('-')) paths.push(x)
  }
  const out = await git(run, f.cwd, ...probe, '--', ...paths)
  const rel = parseCleanDryRun(out)
  if (!f.cwd) throw new Error('the working directory is not known')
  const targets = rel.map(p => ({ raw: p, path: normalize(`${f.cwd}/${p}`), glob: false }))
  if (targets.length === 0) return { ...empty(), notes: ['git clean -n finds nothing to remove right now'] }
  const r = await describePaths(run, f, targets, { verb: 'delete (untracked)', expandSingleDir: false, cap: 300, canLower: false }, cfg)
  r.action = `deletes ${plural(targets.length, 'untracked path')}`
  if (!letters.has('x') && !letters.has('X')) r.notes.push('Ignored files are kept (no -x)')
  r.risk = { level: 'high', headline: `${plural(targets.length, 'untracked path')} never committed, gone for good${letters.has('x') || letters.has('X') ? ' (includes ignored files)' : ''}` }
  return r
}

async function gitReset(run: Run, f: Finding, cfg: Config) {
  const ref = pos(f.args).find(a => REF.test(a)) ?? 'HEAD'
  if (!REF.test(ref)) throw new Error(`unusual ref "${ref}"`)
  const files = parseNameStatus(await git(run, f.cwd, 'diff', '--name-status', ref))
  const stat = (await git(run, f.cwd, 'diff', '--shortstat', ref)).trim()
  const lost = lines(await git(run, f.cwd, 'log', '--oneline', '-n', String(cfg.maxListed + 1), `${ref}..HEAD`))
  const r = empty()
  r.groups.push(cap('Changes lost', files, cfg.maxListed))
  if (lost.length) r.groups.push(cap('Commits leaving the branch', lost, cfg.maxListed))
  r.action = `discards uncommitted changes${files.length ? ` in ${plural(files.length, 'file')}` : ''}`
  r.summary.push(stat || 'no uncommitted changes to tracked files')
  r.notes.push('Untracked files are not touched')
  r.risk = files.length
    ? { level: 'high', headline: `uncommitted changes to ${plural(files.length, 'tracked file')}, gone for good (not in the reflog)` }
    : lost.length ? { level: 'medium', headline: 'commits leave the branch; git reflog can bring them back' }
    : { level: 'low', headline: 'nothing uncommitted to lose' }
  return r
}

async function gitDiscard(run: Run, f: Finding, cfg: Config) {
  const a = f.args
  const dd = a.indexOf('--')
  const before = (dd < 0 ? a : a.slice(0, dd)).filter(x => !x.startsWith('-'))
  const after = dd < 0 ? [] : a.slice(dd + 1)
  const source = a.find(x => x.startsWith('--source='))?.slice(9)
  const tree = source ?? (dd >= 0 ? before.find(x => REF.test(x)) : undefined)
  if (tree !== undefined && !REF.test(tree)) throw new Error(`unusual ref "${tree}"`)
  const paths = after.length ? after : dd < 0 ? before : []
  const spec = ['--name-status', ...(tree ? [tree] : paths.length ? [] : ['HEAD']), '--', ...(paths.length ? paths : ['.'])]
  const files = parseNameStatus(await git(run, f.cwd, 'diff', ...spec))
  const stat = (await git(run, f.cwd, 'diff', '--shortstat', ...spec.filter(s => s !== '--name-status'))).trim()
  const r = empty()
  r.groups.push(cap('Changes lost', files, cfg.maxListed))
  r.action = `discards uncommitted changes${files.length ? ` in ${plural(files.length, 'file')}` : ''}`
  r.summary.push(stat || 'no uncommitted changes to tracked files here')
  r.notes.push('Untracked files are not touched')
  r.risk = files.length
    ? { level: 'high', headline: `uncommitted changes to ${plural(files.length, 'tracked file')}, gone for good` }
    : { level: 'low', headline: 'nothing uncommitted to lose here' }
  return r
}

async function gitPush(run: Run, f: Finding, cfg: Config) {
  const a = f.args
  if (a.some(x => ['--all', '--mirror', '--tags'].includes(x))) throw new Error('pushes every ref: cannot enumerate')
  const operands = pos(a)
  const remote = operands[0]
  const specs = operands.slice(1)
  const pairs = specs.length
    ? specs.map(s => {
        const body = s.replace(/^\+/, '')
        const [src, dst] = body.includes(':') ? [body.split(':')[0]!, body.split(':').slice(1).join(':')] : [body, body]
        return { src, dst: dst.replace(/^refs\/heads\//, '') }
      })
    : [{ src: 'HEAD', dst: '' }]
  const deleting = a.includes('--delete') || a.includes('-d')
  const r = empty()
  for (const p of pairs) {
    const src = deleting && p.src === p.dst ? '' : p.src
    const dstRef = p.dst === '' || !remote ? '@{u}' : `${remote}/${p.dst}`
    for (const ref of [src, dstRef]) if (ref !== '' && !REF.test(ref)) throw new Error(`unusual ref "${ref}"`)
    if (src === '') {
      const tip = lines(await git(run, f.cwd, 'log', '--oneline', '-n', '5', dstRef))
      r.groups.push(cap(`${dstRef} is deleted; latest commits`, tip, cfg.maxListed))
      r.action = `deletes ${dstRef} on the remote`
      continue
    }
    const over = lines(await git(run, f.cwd, 'log', '--oneline', '-n', String(cfg.maxListed + 1), `${src}..${dstRef}`))
    const sent = lines(await git(run, f.cwd, 'log', '--oneline', '-n', String(cfg.maxListed + 1), `${dstRef}..${src}`))
    r.groups.push(cap(`Overwritten on ${dstRef}`, over, cfg.maxListed))
    r.groups.push(cap(`Sent from ${src}`, sent, cfg.maxListed))
    r.action ??= `force-pushes over ${dstRef}`
    r.summary.push(`${plural(over.length, 'remote commit')} lost, ${plural(sent.length, 'commit')} sent`)
    if (over.length) r.risk = { level: 'high', headline: `${plural(over.length, 'remote commit')} overwritten for anyone who has not pulled them` }
  }
  r.notes.push('Remote state is as of your last fetch')
  return r
}

async function gitBranch(run: Run, f: Finding, cfg: Config) {
  const r = empty()
  for (const b of pos(f.args)) {
    if (!REF.test(b)) throw new Error(`unusual branch name "${b}"`)
    const only = lines(await git(run, f.cwd, 'log', '--oneline', '-n', String(cfg.maxListed + 1), b, '--not', `--exclude=${b}`, '--branches', '--tags', '--remotes'))
    const tip = (await git(run, f.cwd, 'rev-parse', '--short', b)).trim()
    r.groups.push(cap(
      only.length ? `Only on ${b}` : `${b}: every commit is also elsewhere`, only, cfg.maxListed,
    ))
    r.notes.push(`Undo: git branch ${b} ${tip}`)
    r.action = `deletes branch ${pos(f.args).join(', ')}`
    if (only.length) r.risk = { level: 'high', headline: `${plural(only.length, 'commit')} on ${b} exist on no other branch, tag or remote` }
  }
  return r
}

async function gitStash(run: Run, f: Finding, cfg: Config) {
  const op = f.args[0]
  const r = empty()
  if (op === 'clear') {
    const all = lines(await git(run, f.cwd, 'stash', 'list'))
    r.groups.push(cap('Stashes deleted', all, cfg.maxListed))
    r.action = 'deletes all stashes'
    r.summary.push(plural(all.length, 'stash', 'stashes'))
    r.risk = { level: 'high', headline: `${plural(all.length, 'stash', 'stashes')} of uncommitted work exist nowhere else` }
    return r
  }
  const ref = f.args.slice(1).find(x => !x.startsWith('-')) ?? 'stash@{0}'
  if (!/^stash@\{\d+\}$/.test(ref)) throw new Error(`unusual stash ref "${ref}"`)
  const stat = lines(await git(run, f.cwd, 'stash', 'show', '--stat', ref))
  r.groups.push(cap(`${ref} holds`, stat.slice(0, -1), cfg.maxListed))
  r.action = `deletes ${ref}`
  r.summary.push(stat.at(-1)?.trim() ?? ref)
  r.notes.push('git fsck --unreachable can still find a dropped stash until gc runs')
  r.risk = { level: 'high', headline: 'stashed work exists nowhere else' }
  return r
}

export async function measureAll(run: Run, findings: Finding[], cfg: Config, max = 6): Promise<{ reports: Report[]; unlisted: number }> {
  const reports: Report[] = []
  for (const f of findings.slice(0, max)) {
    const rep = await measure(run, f, cfg)
    if (!rep.skip) reports.push(rep)
  }
  return { reports, unlisted: Math.max(0, findings.length - max) }
}

files.hooks/windows.ts:
// Native Windows handling: the measurer's probes are Unix `find` and `du`, which do not exist there (Windows has its own
// `find`, a text search, that would answer nothing and make a destructive command look harmless). So on Windows a risky
// command is held WITHOUT a listing, saying so, instead of being measured.
import type { Finding } from './classify'
import type { Report } from './measure'

export const WINDOWS_NOTE = 'Nothing can be listed on Windows. Check the path yourself first'

/** A drive-letter or UNC path: `C:\Users\me`, `C:/Users/me`, `\\server\share`. */
export const looksWindows = (p: string | undefined): boolean => p !== undefined && /^([A-Za-z]:[\\/]|\\\\)/.test(p)

/** Reports that say plainly nothing was measured. Conditional findings (`> file`) need a file check, so they pass. */
export function unmeasured(found: Finding[]): { reports: Report[]; unlisted: number } {
  const held = found.filter(f => f.conditional === undefined)
  return {
    reports: held.slice(0, 6).map(f => ({ finding: f, groups: [], summary: [], notes: [WINDOWS_NOTE], unmeasured: 'native Windows' })),
    unlisted: Math.max(0, held.length - 6),
  }
}

files.hooks/lex.ts:
// A small POSIX-shell lexer: just enough to find the simple commands in a Bash
// tool call. It never evaluates anything. Quotes are removed, `$(...)`, backticks
// and `<(...)` bodies are captured as `subs` (classified recursively), and anything
// that expands at run time (`$VAR`, `${..}`, `{a,b}`, `$(..)`) marks the word `dynamic`.

export type Word = {
  text: string
  glob: boolean // an unquoted * ? or [..] is in it
  dynamic: boolean // its value is only known at run time
  tilde: boolean // starts with an unquoted ~
  subs: string[] // command substitutions found inside it
}

export type Tok =
  | { t: 'word'; w: Word }
  | { t: 'op'; op: ';' | '&&' | '||' | '|' | '&' | '(' | ')' }
  | { t: 'redir'; op: string; fd?: string; body?: string }

const blank = (): Word => ({ text: '', glob: false, dynamic: false, tilde: false, subs: [] })
const NAME = /[A-Za-z0-9_]/
// Sticky regexes: tested in place, so a long command is not re-sliced at every bracket.
const BRACKET = /\[[^\s\]]+\]/y
const BRACE = /\{[^\s{}]*(,|\.\.)[^\s{}]*\}/y
const REDIR = /(&>>|&>|>>|>\||>&|<<<|<<-|<<|<&|<>|>|<)/y
const at = (re: RegExp, s: string, i: number) => ((re.lastIndex = i), re.exec(s))

// Index of the `close` char matching an already-opened `open`, quote aware; -1 if none.
function matchClose(src: string, from: number, open: string, close: string): number {
  let depth = 1
  for (let i = from; i < src.length; i++) {
    const c = src[i]
    if (c === '\\') i++
    else if (c === "'") {
      const j = src.indexOf("'", i + 1)
      if (j < 0) return -1
      i = j
    } else if (c === '"') {
      let j = i + 1
      while (j < src.length && src[j] !== '"') j += src[j] === '\\' ? 2 : 1
      if (j >= src.length) return -1
      i = j
    } else if (c === close) {
      if (open === close || --depth === 0) return i
    } else if (c === open) depth++
  }
  return -1
}

type Pending = { tok: Extract<Tok, { t: 'redir' }>; delim: string; strip: boolean }

export function lex(src: string): Tok[] {
  const toks: Tok[] = []
  const heredocs: Pending[] = []
  let cur: Word | undefined
  let expectDelim: { tok: Extract<Tok, { t: 'redir' }>; strip: boolean } | undefined
  let i = 0

  const word = () => (cur ??= blank())
  const flush = () => {
    if (!cur) return
    toks.push({ t: 'word', w: cur })
    if (expectDelim) heredocs.push({ ...expectDelim, delim: cur.text })
    expectDelim = undefined
    cur = undefined
  }
  const op = (o: Extract<Tok, { t: 'op' }>['op']) => {
    flush()
    toks.push({ t: 'op', op: o })
  }
  // `$(..)`, backticks, `<(..)`: the body is kept for recursive classification.
  const capture = (open: string, close: string, openAt: number, rawFrom: number): number => {
    const end = matchClose(src, openAt + 1, open, close)
    const stop = end < 0 ? src.length : end
    const w = word()
    w.subs.push(src.slice(openAt + 1, stop))
    w.dynamic = true
    w.text += src.slice(rawFrom, stop + 1)
    return stop
  }
  const readBodies = () => {
    for (const h of heredocs.splice(0)) {
      const lines: string[] = []
      while (i < src.length) {
        const nl = src.indexOf('\n', i)
        const line = src.slice(i, nl < 0 ? src.length : nl)
        i = nl < 0 ? src.length : nl + 1
        if ((h.strip ? line.replace(/^\t+/, '') : line) === h.delim) break
        lines.push(line)
      }
      h.tok.body = lines.join('\n')
    }
  }
  // A `$` outside single quotes. `quoted` = inside double quotes.
  const dollar = (quoted: boolean) => {
    const n = src[i + 1]
    if (n === '(') i = capture('(', ')', i + 1, i)
    else if (n === '{') {
      const end = matchClose(src, i + 2, '{', '}')
      const stop = end < 0 ? src.length - 1 : end
      const w = word()
      w.text += src.slice(i, stop + 1)
      w.dynamic = true
      i = stop
    } else if (n === "'" && !quoted) {
      const end = src.indexOf("'", i + 2)
      word().text += src.slice(i + 2, end < 0 ? src.length : end)
      i = end < 0 ? src.length : end
    } else if (n !== undefined && (NAME.test(n) || '@*#?!$-'.includes(n))) {
      let j = i + 1
      if (NAME.test(n)) while (j + 1 < src.length && NAME.test(src[j + 1]!)) j++
      const w = word()
      w.text += src.slice(i, j + 1)
      w.dynamic = true
      i = j
    } else word().text += '$'
  }

  while (i < src.length) {
    const c = src[i]!
    if (c === ' ' || c === '\t' || c === '\r') flush()
    else if (c === '\n') {
      op(';')
      i++
      readBodies()
      continue
    } else if (c === '#' && !cur) {
      while (i < src.length && src[i] !== '\n') i++
      continue
    } else if (c === '\\') {
      if (src[i + 1] === '\n') i++
      else {
        word().text += src[i + 1] ?? ''
        i++
      }
    } else if (c === "'") {
      const end = src.indexOf("'", i + 1)
      word().text += src.slice(i + 1, end < 0 ? src.length : end)
      i = end < 0 ? src.length : end
    } else if (c === '"') {
      word()
      i++
      while (i < src.length && src[i] !== '"') {
        const d = src[i]!
        if (d === '\\' && '$"`\\\n'.includes(src[i + 1] ?? 'x')) {
          if (src[i + 1] !== '\n') word().text += src[i + 1]
          i++
        } else if (d === '$') dollar(true)
        else if (d === '`') i = capture('`', '`', i, i)
        else word().text += d
        i++
      }
    } else if (c === '`') i = capture('`', '`', i, i)
    else if (c === '$') dollar(false)
    else if ((c === '<' || c === '>') && src[i + 1] === '(') i = capture('(', ')', i + 1, i)
    else if (c === '<' || c === '>' || (c === '&' && src[i + 1] === '>')) {
      const fd = cur && /^\d+$/.test(cur.text) ? cur.text : undefined
      if (fd !== undefined) cur = undefined
      flush()
      const m = at(REDIR, src, i)!
      const tok: Extract<Tok, { t: 'redir' }> = { t: 'redir', op: m[1]!, ...(fd ? { fd } : {}) }
      toks.push(tok)
      if (tok.op === '<<' || tok.op === '<<-') expectDelim = { tok, strip: tok.op === '<<-' }
      i += m[1]!.length - 1
    } else if (c === ';') op(';')
    else if (c === '&') {
      if (src[i + 1] === '&') (op('&&'), i++)
      else op('&')
    } else if (c === '|') {
      if (src[i + 1] === '|') (op('||'), i++)
      else {
        op('|')
        if (src[i + 1] === '&') i++
      }
    } else if (c === '(' || c === ')') op(c)
    else {
      const w = word()
      if (c === '*' || c === '?') w.glob = true
      else if (c === '[' && at(BRACKET, src, i)) w.glob = true
      else if (c === '{' && at(BRACE, src, i)) w.dynamic = true
      else if (c === '~' && w.text === '') w.tilde = true
      w.text += c
    }
    i++
  }
  flush()
  return toks
}

files.hooks/folder.ts:
// Folder risk: for every DIRECTORY a held command would delete, overwrite or change recursively, answer in a few
// short rows: where the folder sits (repository root, folder inside a repository, outside any repository), what kind of
// content it holds (build output that can be regenerated, source, data that is hard to regenerate, likely secrets),
// how big it is and how recently something in it changed, what git could give back, and ONE closing row
// "Recoverable: Yes / Partly / No" that also sets the risk level.
//
// Everything is a heuristic from names and git state, and the wording says so. Probes are read-only argv arrays through
// `run` (find, du, git: nothing a shell could evaluate), bounded three ways: a probe timeout, a cap on how many files
// are classified ("sampled" is said when it bites), and a stop at the first tree walk that times out.
// Contract like the rest of the measurer: never throws; a scan that did not finish never reads as LOW.
import { GIT, statusEntries, wholeRepoFact } from './recover'
import type { RiskLevel } from './recover'
import type { Run, RunResult } from './measure'

export type Mode = 'delete' | 'modify' | 'overwrite' // what the command does to the folder
export type Recoverable = 'yes' | 'partly' | 'no' | 'unknown'
export type Row = [label: string, value: string]
export type FolderRisk = {
  path: string
  title: string // "data/ · High"
  level: RiskLevel
  rows: Row[] // [label, value] pairs, already worded; the last one is "Recoverable"
  headline: string // one short phrase for the overall impact line (no full stop)
  regenerable: boolean // true only when everything found is build/cache output by name
  onlyRepos?: boolean // a folder outside git that holds nothing but whole repositories (all of them safe)
  complete: boolean // false when the scan stopped early or failed: such a result never lowers a risk level
}
export type Known = { kb?: number; files?: number; filesLowerBound?: boolean }
export type FolderContext = {
  home?: string
  cwd?: string // the session's directory
  runCwd?: string // the directory the command runs in (after a `cd`)
  mode: Mode
  maxFolders?: number
  known?: Map<string, Known> // sizes and counts the caller already measured
  note?: string // e.g. cargo clean: the caller says this is build output
}

export const SAMPLE_CAP = 3000 // files classified at most; more is "sampled"
export const FOLDER_PROBE_MS = 8000
const SIZE_CAP = 240 // files sized with du, data and secrets first
const NESTED_CAP = 5
const BANDS: [number, string][] = [
  [15, 'within 15 minutes'], [60, 'within the hour'], [360, 'within 6 hours'],
  [1440, 'within a day'], [10080, 'within a week'], [43200, 'within 30 days'],
]
const LEVEL_WORD: Record<RiskLevel, string> = { high: 'High', medium: 'Medium', low: 'Low', unknown: 'Unknown' }
const cap1 = (s: string) => s.charAt(0).toUpperCase() + s.slice(1)

const lines = (s: string) => s.split('\n').map(l => l.replace(/\r$/, '')).filter(l => l !== '')
const fmt = (n: number) => n.toLocaleString('en-US')
const plural = (n: number, w: string, many = w + 's') => `${fmt(n)} ${n === 1 ? w : many}`
const inside = (child: string, parent: string) => child === parent || child.startsWith(parent === '/' ? '/' : parent + '/')
const base = (p: string) => p.slice(p.lastIndexOf('/') + 1)
const parentOf = (p: string) => (p.lastIndexOf('/') > 0 ? p.slice(0, p.lastIndexOf('/')) : '/')
const clip = (s: string, n: number) => (s.length > n ? s.slice(0, n - 1) + '…' : s)
const sum = (a: number[]) => a.reduce((x, y) => x + y, 0)
const chunks = <T>(a: T[], n: number) => Array.from({ length: Math.ceil(a.length / n) }, (_, k) => a.slice(k * n, (k + 1) * n))
export function kbText(kb: number): string {
  const u = ['KB', 'MB', 'GB', 'TB']
  let v = kb
  let k = 0
  while (v >= 1024 && k < u.length - 1) (v /= 1024, k++)
  return `${+v.toFixed(v >= 10 || k === 0 ? 0 : 1)} ${u[k]}`
}
function duMap(out: string): Map<string, number> {
  const m = new Map<string, number>()
  for (const l of lines(out)) {
    const hit = /^(\d+)\s+(.*)$/.exec(l)
    if (hit) m.set(hit[2]!, Number(hit[1]))
  }
  return m
}

// ---- names: what a folder or file probably is -------------------------------------------------

export type Cls = 'regen' | 'data' | 'secret' | 'source' | 'other'

/** Directory names that are build or cache output almost everywhere (pruned from the file listing, sized as a whole). */
export const REGEN_NAMES = [
  'node_modules', '__pycache__', '.venv', 'venv', '.cache', '.Rproj.user', '.pytest_cache', '.mypy_cache', '.ruff_cache',
  '.tox', '.gradle', '.next', '.nuxt', '.ipynb_checkpoints', '.eggs', '.parcel-cache', '.sass-cache', '.Rcache',
  '*.Rcheck', '*.egg-info', 'target', 'build', 'dist', '_build', '_site', 'htmlcov',
]
// Build output only by convention: a folder called build or dist can also hold something somebody wrote.
const GENERIC = new Set(['target', 'build', 'dist', '_build', '_site', '.cache'])
const RENV_LIBRARY = '*/renv/library' // R package library managed by renv

const regenName = (name: string) => REGEN_NAMES.some(n => (n.startsWith('*') ? name.endsWith(n.slice(1)) : name === n))

/** Which part of the folder's own path makes all of it build output (its name or a specific parent), or undefined. */
export function regenContext(dir: string): string | undefined {
  const parts = dir.split('/').filter(Boolean)
  for (let k = 0; k < parts.length; k++) {
    const p = parts[k]!
    if (p === 'library' && parts[k - 1] === 'renv') return 'renv/library'
    if (regenName(p) && (k === parts.length - 1 || !GENERIC.has(p))) return p
  }
  return undefined
}

const DATA_EXT = new Set((
  'csv tsv rds rda rdata vcf bcf bam cram sam bai fam bed bim ped map gds bgen pgen pvar psam h5 hdf5 hdf parquet feather ' +
  'arrow xlsx xls ods fasta fa fna faa fastq fq gtf gff gff3 gz bz2 xz zst zip tar tgz 7z sqlite sqlite3 db ipynb tex bib ' +
  'docx doc odt pdf pptx key npy npz mat sav dta sas7bdat rdb rdx qs fst'
).split(' '))
const SOURCE_EXT = new Set((
  'r py rs js mjs ts tsx jsx c h cc cpp hpp java go sh bash zsh jl sql md rmd qmd rst toml yaml yml json cfg ini css html ' +
  'cmake lock txt nf smk pl rb'
).split(' '))
const SOURCE_NAMES = new Set(['makefile', 'dockerfile', 'license', 'readme', 'description', 'namespace', 'snakefile'])

/** Name-only guess for one file. Never reads the file. */
export function classifyName(name: string): Exclude<Cls, 'regen'> {
  const n = name.toLowerCase()
  if (n === '.env' || n.startsWith('.env.') || /\.(pem|key|p12|pfx|kdbx|keystore)$/.test(n)) return 'secret'
  if (['.netrc', '.npmrc', '.pypirc', '.renviron', 'credentials'].includes(n)) return 'secret'
  if (n.startsWith('id_') && !n.endsWith('.pub')) return 'secret'
  const ext = n.includes('.') ? n.slice(n.lastIndexOf('.') + 1) : ''
  if (DATA_EXT.has(ext)) return 'data'
  if (SOURCE_EXT.has(ext) || SOURCE_NAMES.has(n)) return 'source'
  return 'other'
}

const CLASS_WORDS: Record<Exclude<Cls, 'regen'>, [string, string]> = {
  data: ['data file', 'data files'], secret: ['likely secret file', 'likely secret files'],
  source: ['source file', 'source files'], other: ['other file', 'other files'],
}

// ---- where the folder sits ----------------------------------------------------------------------

const SYNC = /(^|\/)(Dropbox[^/]*|OneDrive[^/]*|Google ?Drive[^/]*|GoogleDrive[^/]*|iCloud ?Drive[^/]*|Mobile Documents|com~apple~CloudDocs|pCloud ?Drive|Box Sync|Library\/CloudStorage)(\/|$)/i
const SYSTEM_TOP = /^\/(usr|etc|var|bin|sbin|lib|lib32|lib64|opt|boot|dev|proc|sys|run|root|home|Users|System|Library|Applications|Volumes|private|mnt|media|tmp)$/
const HOME_FOLDERS = /^(Desktop|Documents|Downloads|Pictures|Music|Movies|Videos|Library|Applications|Public)$/i

/** A hedged hint when the path looks like it lives in a synced folder, or in a folder iCloud may sync. */
export function syncHint(path: string, home?: string): string | undefined {
  const m = SYNC.exec(path)
  if (m) {
    const name = /^(Mobile Documents|com~apple~CloudDocs)$/i.test(m[2]!) ? 'iCloud Drive' : /^Library\/CloudStorage$/i.test(m[2]!) ? 'cloud storage' : m[2]!
    return `Looks synced (${name}): deletes may reach your other devices; its trash may keep a copy (not checked)`
  }
  if (home && parentOf(path) === home && /^(Desktop|Documents)$/i.test(base(path)))
    return 'Desktop and Documents may sync with iCloud (not checked): a delete could reach your other devices'
  return undefined
}

export type Critical = { reason: string; skipScan: boolean }

/** CRITICAL targets: root, home and its parents, top-level system folders, the usual home folders, the working directory or a parent of it. */
export function criticalReason(dir: string, ctx: { home?: string; cwd?: string; runCwd?: string }): Critical | undefined {
  const { home } = ctx
  if (dir === '/') return { reason: 'the filesystem root', skipScan: true }
  if (home && dir === home) return { reason: 'your home folder', skipScan: true }
  if (home && inside(home, dir)) return { reason: 'a parent of your home folder', skipScan: true }
  if (SYSTEM_TOP.test(dir)) return { reason: 'a top-level system folder', skipScan: true }
  if (home && parentOf(dir) === home && HOME_FOLDERS.test(base(dir))) return { reason: `your ${base(dir)} folder`, skipScan: false }
  for (const [where, label] of [[ctx.runCwd, 'the folder the command runs in'], [ctx.cwd, 'the current working directory']] as const) {
    if (where === undefined || !inside(where, dir)) continue
    return { reason: where === dir ? label : `a parent of ${label}`, skipScan: false }
  }
  return undefined
}

// ---- git view of one folder ---------------------------------------------------------------------

type Bucket = 'pushed' | 'local' | 'changed' | 'untracked' | 'ignored' | 'outside'
type PathSet = { exact: Set<string>; dirs: Set<string>; all: string[] } // dirs: collapsed directories, with a trailing '/'
type GitView = {
  root: string // the logical root: where git runs
  isRoot: boolean // the folder IS the repository root (its .git goes with it)
  noRemote: boolean
  changed: PathSet; untracked: PathSet; ignored: PathSet
  touched: PathSet // files in commits that no remote has
  unpushedCommits: number
  tracked: string[] // absolute paths
}

function pathSet(abs: string[]): PathSet {
  return { exact: new Set(abs.filter(p => !p.endsWith('/'))), dirs: new Set(abs.filter(p => p.endsWith('/'))), all: abs }
}
// `path` is listed, or lies below a collapsed directory that is listed
function covers(s: PathSet, path: string): boolean {
  if (s.exact.has(path)) return true
  for (let i = path.indexOf('/', 1); i > 0; i = path.indexOf('/', i + 1)) if (s.dirs.has(path.slice(0, i + 1))) return true
  return s.dirs.has(path + '/')
}
const hasBelow = (s: PathSet, dir: string) => s.all.some(e => e.startsWith(dir + '/'))

function bucketOf(path: string, isDir: boolean, g: GitView): Bucket {
  if (covers(g.changed, path) || (isDir && hasBelow(g.changed, path))) return 'changed'
  if (covers(g.untracked, path) || (isDir && hasBelow(g.untracked, path))) return 'untracked'
  if (covers(g.ignored, path) || (isDir && hasBelow(g.ignored, path))) return 'ignored'
  if (g.noRemote || covers(g.touched, path) || (isDir && hasBelow(g.touched, path))) return 'local'
  return 'pushed'
}

type Probe = (argv: string[], cwd?: string) => Promise<RunResult | undefined>

// null: the folder is not inside any repository
async function gitView(run: Run, dir: string): Promise<GitView | null> {
  const gitRun = (cwd: string, ...argv: string[]) => run([...GIT, ...argv], cwd)
  const top = await gitRun(dir, 'rev-parse', '--show-toplevel', '--show-prefix')
  if (top.exitCode !== 0) return null
  const [toplevel = '', prefix = ''] = top.stdout.split('\n').map(l => l.replace(/\r$/, ''))
  const rel = prefix.replace(/\/$/, '')
  // git reports the real path; keep the path the user typed so that every path below matches the listing
  const root = !rel ? dir : dir.endsWith('/' + rel) ? dir.slice(0, dir.length - rel.length - 1) : toplevel
  const spec = rel ? ['--', rel] : []
  const remotes = lines((await gitRun(root, 'remote')).stdout)
  const status = await gitRun(root, 'status', '--porcelain=v1', '-z', '--ignored', ...spec)
  if (status.exitCode !== 0) throw new Error(`git status failed: ${status.stderr.trim().split('\n')[0] || `exit ${status.exitCode}`}`)
  const ents = statusEntries(status.stdout).map(e => ({ xy: e.xy, abs: `${root}/${e.path}` }))
  const lost = (xy: string) => xy !== '??' && xy !== '!!' && !(xy === ' D' || xy === 'D ')
  const files = await gitRun(root, 'ls-files', '-z', ...spec)
  const unpushed = remotes.length
    ? await gitRun(root, '-c', 'core.quotepath=off', 'log', '--name-only', '--format=%x01%h', '-n', '300', 'HEAD', '--not', '--remotes', ...spec)
    : undefined
  const touched: string[] = []
  let commits = 0
  for (const l of lines(unpushed?.exitCode === 0 ? unpushed.stdout : '')) {
    if (l.startsWith('\x01')) commits++
    else touched.push(`${root}/${l}`)
  }
  return {
    root, isRoot: !rel, noRemote: remotes.length === 0,
    changed: pathSet(ents.filter(e => lost(e.xy)).map(e => e.abs)),
    untracked: pathSet(ents.filter(e => e.xy === '??').map(e => e.abs)),
    ignored: pathSet(ents.filter(e => e.xy === '!!').map(e => e.abs)),
    touched: pathSet(touched), unpushedCommits: commits,
    tracked: files.stdout.split('\0').filter(Boolean).map(p => `${root}/${p}`),
  }
}

// ---- the listing --------------------------------------------------------------------------------

/** `( -type d ( -name n1 -o -name n2 ... ) -prune )`: build/cache directories and .git directories are not entered. */
export function pruneExpr(): string[] {
  const names = REGEN_NAMES.flatMap((n, k) => [...(k ? ['-o'] : []), '-name', n])
  return ['(', '-type', 'd', '(', ...names, '-o', '-path', RENV_LIBRARY, '-o', '-name', '.git', ')', '-prune', ')']
}

type Entry = { path: string; dir: boolean; cls: Cls; bucket: Bucket; kb?: number }
type Scan = {
  dir: string; mode: Mode; git: GitView | null
  entries: Entry[]; sampled: boolean; listed: number
  gitDirs: string[] // .git directories found below the folder, other than its own
  nested: { root: string; text: string; atStake: boolean }[]; nestedMore: number
  totalKb?: number; files?: number; filesLowerBound?: boolean
  newest?: string; newestCount?: number; newestMins?: number
  links: number; crossesFs: boolean
  ctxRegen?: string; partial: boolean; whole?: { text: string; atStake: boolean }
}

async function scanFolder(light: Run, heavy: Probe, state: { slow: boolean }, dir: string, ctx: FolderContext): Promise<Scan> {
  const known = ctx.known?.get(dir)
  const git = await gitView(light, dir)
  // a build/ or dist/ that git tracks holds committed files: judge it by what is in it, not by its name
  const ctxRegen = git && git.tracked.length > 0 ? undefined : regenContext(dir)
  const expr = pruneExpr()
  const walk = (...tail: string[]) => ['find', dir, '-mindepth', '1', ...expr, ...tail]

  // build/cache and .git directories (not entered), then the other files, capped
  const prunedOut = await heavy(['find', dir, '-mindepth', '1', ...expr.slice(1, -1), '-print'])
  const prunedAll = lines(prunedOut?.stdout ?? '')
  const ownGit = `${dir}/.git`
  const gitDirs = prunedAll.filter(p => base(p) === '.git' && p !== ownGit)
  const prunedRegen = prunedAll.filter(p => base(p) !== '.git')
  const listRes = ctxRegen ? undefined : await heavy(walk('-o', '-type', 'f', '-print'))
  const listed = lines(listRes?.stdout ?? '')
  const sampled = listed.length > SAMPLE_CAP || !!listRes?.isStdoutTruncated
  const files = listed.slice(0, SAMPLE_CAP)

  const s: Scan = {
    dir, mode: ctx.mode, git, entries: [], sampled, listed: listed.length, gitDirs, nested: [], nestedMore: 0,
    totalKb: known?.kb, files: known?.files, filesLowerBound: known?.filesLowerBound,
    links: 0, crossesFs: false, ctxRegen, partial: false,
  }
  if (!ctxRegen && git?.isRoot) s.whole = await wholeRepoFact(light, git.root, git.noRemote)

  // nested repositories: their .git goes too; look at the first few
  const roots = gitDirs.map(p => p.slice(0, -5))
  s.nestedMore = Math.max(0, roots.length - NESTED_CAP)
  for (const root of roots.slice(0, NESTED_CAP)) s.nested.push({ root, ...(await nestedFact(light, root)) })
  const nestedIn = (p: string) => roots.some(r => p.startsWith(r + '/'))

  const where = (p: string, isDir: boolean): Bucket => (git ? bucketOf(p, isDir, git) : 'outside')
  for (const p of files)
    if (!nestedIn(p)) s.entries.push({ path: p, dir: false, cls: ctxRegen ? 'regen' : classifyName(base(p)), bucket: where(p, false) })
  for (const p of prunedRegen.filter(q => !nestedIn(q))) {
    const tracked = git?.tracked.some(t => t.startsWith(p + '/')) ?? false
    const cls: Cls = GENERIC.has(base(p)) && tracked ? 'source' : 'regen' // a committed dist/ or build/ is not just build output
    s.entries.push({ path: p, dir: true, cls, bucket: where(p, true) })
  }
  if (ctxRegen) s.entries.push({ path: dir, dir: true, cls: 'regen', bucket: where(dir, true) })

  // sizes: regenerable directories as a whole, data and secrets one by one, the folder in total
  await sizes(heavy, s, ctxRegen !== undefined)
  if (s.totalKb === undefined && !state.slow) s.totalKb = parseTotal(await heavy(['du', '-sk', dir]), dir)
  if (!ctxRegen && !state.slow) await recency(heavy, s, walk)
  if (!state.slow) s.links = lines((await heavy(walk('-o', '-type', 'l', '-print')))?.stdout ?? '').length
  if (!state.slow && s.totalKb !== undefined) {
    const one = parseTotal(await heavy(['du', '-skx', dir]), dir)
    s.crossesFs = one !== undefined && s.totalKb - one > Math.max(64, s.totalKb * 0.01)
  }
  s.partial = state.slow
  return s
}

const parseTotal = (r: RunResult | undefined, dir: string) => (r ? duMap(r.stdout).get(dir) : undefined)

async function sizes(heavy: Probe, s: Scan, regenOnly: boolean): Promise<void> {
  const dirs = s.entries.filter(e => e.dir && e.path !== s.dir)
  if (dirs.length) {
    const m = duMap((await heavy(['du', '-sk', ...dirs.slice(0, 40).map(e => e.path)]))?.stdout ?? '')
    for (const e of dirs) e.kb = m.get(e.path)
  }
  if (regenOnly) return
  const order: Cls[] = ['data', 'secret']
  const picked = s.entries.filter(e => !e.dir && order.includes(e.cls)).slice(0, SIZE_CAP)
  for (const part of chunks(picked, 60)) {
    const m = duMap((await heavy(['du', '-k', ...part.map(e => e.path)]))?.stdout ?? '')
    for (const e of part) e.kb = m.get(e.path)
  }
}

async function recency(heavy: Probe, s: Scan, walk: (...tail: string[]) => string[]): Promise<void> {
  for (const [mins, label] of BANDS) {
    const r = await heavy(walk('-o', '-type', 'f', '-mmin', `-${mins}`, '-print'))
    if (!r) return
    const n = lines(r.stdout).length
    if (n > 0) {
      s.newest = label
      s.newestCount = n
      s.newestMins = mins
      return
    }
  }
  s.newest = 'not edited in 30 days'
}

async function nestedFact(light: Run, root: string): Promise<{ text: string; atStake: boolean }> {
  try {
    const remote = await light([...GIT, 'remote'], root)
    const fact = await wholeRepoFact(light, root, lines(remote.stdout).length === 0)
    const st = await light([...GIT, 'status', '--porcelain=v1', '-z'], root)
    const dirty = statusEntries(st.stdout).length
    return { text: dirty ? `${fact.text}, ${plural(dirty, 'uncommitted path')}` : fact.text, atStake: fact.atStake || dirty > 0 }
  } catch (err) {
    return { text: `${root}/  state unknown (${clip((err as Error).message, 60)})`, atStake: true }
  }
}

// ---- the verdict --------------------------------------------------------------------------------

type Verdict = { level: RiskLevel; recoverable: Recoverable; because: string; headline: string; onlyRepos: boolean; gitLine?: string; stake: string[] }

function count<T>(a: T[], f: (x: T) => boolean) {
  return a.filter(f).length
}

function judge(s: Scan, crit: Critical | undefined): Verdict {
  const e = s.entries
  const real = e.filter(x => x.cls !== 'regen')
  const lostBy = (b: Bucket) => real.filter(x => x.bucket === b)
  const changed = lostBy('changed'), untracked = lostBy('untracked'), outside = lostBy('outside'), ignored = lostBy('ignored'), local = lostBy('local')
  const pushed = lostBy('pushed')
  const whole = !!s.git?.isRoot
  const nestedRisk = s.nested.some(n => n.atStake)
  const hard = [...changed, ...untracked, ...outside]
  const hardIgnored = ignored.filter(x => x.cls === 'data' || x.cls === 'secret')
  const softIgnored = ignored.filter(x => x.cls !== 'data' && x.cls !== 'secret')
  // committed but unpushed: restorable from .git while it stays, gone with it when the repository goes whole
  const localLost = whole ? local : []
  const machineOnly = whole ? [] : local
  const noRemote = !!s.git?.noRemote
  const onlyRepos = !s.git && s.entries.length === 0 && s.nested.length > 0 && s.nestedMore === 0 && !nestedRisk && !s.partial

  let level: RiskLevel = 'low'
  if (hard.length || hardIgnored.length || localLost.length || (whole && s.whole?.atStake) || nestedRisk) level = 'high'
  else if (machineOnly.length && !noRemote) level = 'high'
  else if (softIgnored.length || (s.sampled && !s.git)) level = 'medium'
  if (level === 'medium' && s.newestMins !== undefined && s.newestMins <= 1440) level = 'high' // recent edits: active work
  if (s.partial && level === 'low') level = 'unknown'
  if (s.mode === 'modify') level = s.partial ? 'unknown' : real.some(x => x.cls === 'secret') || nestedRisk ? 'medium' : 'low'
  if (crit) level = 'high'

  const lost = hard.length + hardIgnored.length + softIgnored.length + localLost.length
  const bits: string[] = []
  if (s.git) {
    const trackedOk = Math.max(0, s.git.tracked.length - count(s.git.tracked, t => covers(s.git!.changed, t) || covers(s.git!.touched, t)))
    if (trackedOk) bits.push(`${plural(trackedOk, 'file')} pushed`)
    if (s.git.unpushedCommits) bits.push(`${plural(s.git.unpushedCommits, 'commit')} not pushed`)
    else if (noRemote && s.git.tracked.length) bits.push('no remote')
    if (changed.length) bits.push(`${plural(changed.length, 'modified file')}`)
    if (untracked.length) bits.push(`${plural(untracked.length, 'untracked file')}`)
    if (ignored.length) bits.push(`${plural(ignored.length, 'ignored file')}`)
  } else if (outside.length) bits.push(`${plural(outside.length, 'file')}${s.sampled ? ' in the sample' : ''}, no git history`)

  let recoverable: Recoverable
  let because: string
  if (s.partial && !lost) (recoverable = 'unknown', because = 'the scan stopped early, so assume not')
  else if (!lost && !machineOnly.length) {
    recoverable = 'yes'
    because = real.length || s.git?.tracked.length ? 'everything except build output is pushed (as of your last fetch)'
      : s.entries.length ? 'only build output, which a rebuild recreates'
      : onlyRepos ? 'every repository inside is fully pushed' : 'the folder is empty'
  } else if (!lost) {
    recoverable = noRemote ? 'yes' : 'partly'
    because = noRemote ? 'git restore brings files back while .git stays; there is no remote copy' : `${plural(machineOnly.length, 'file')} committed but not pushed come back only from this .git`
  } else {
    recoverable = pushed.length || machineOnly.length ? 'partly' : 'no'
    const gone = [changed.length && 'modified files', untracked.length && 'untracked files', hard.length - changed.length - untracked.length > 0 && 'files outside git', ignored.length && 'ignored files', localLost.length && 'unpushed commits'].filter(Boolean)
    because = `${gone.join(', ')} cannot be restored${pushed.length ? '; pushed files can' : ''}`
  }
  if (recoverable === 'yes' && ((whole && s.whole?.atStake) || nestedRisk)) {
    recoverable = 'partly'
    because = 'commits on no remote, stashes or worktrees exist only in the .git that goes too'
  }
  if (s.mode === 'modify') {
    recoverable = s.partial ? 'unknown' : 'partly'
    because = 'contents stay; old permissions and owners are not recorded'
  }
  if (crit && s.mode !== 'modify') {
    recoverable = 'no'
    because = `${crit.reason} is targeted; assume everything is gone (backups such as Time Machine are not checked)`
  }

  const stake = real
    .filter(x => (x.bucket === 'changed' || x.bucket === 'untracked' || x.bucket === 'outside' || x.bucket === 'ignored' || (whole && x.bucket === 'local')) && (x.cls === 'data' || x.cls === 'secret' || x.bucket === 'changed'))
    .sort((a, b) => (b.kb ?? 0) - (a.kb ?? 0))
    .map(x => `${x.path.startsWith(s.dir + '/') ? x.path.slice(s.dir.length + 1) : x.path}${x.kb !== undefined ? ` (${kbText(x.kb)})` : ''}`)

  const headline = crit
    ? `${cap1(crit.reason)} is targeted`
    : level === 'low'
      ? s.entries.length && !real.length ? 'build output only (regenerable by name)' : onlyRepos ? 'only whole repositories, all fully pushed' : 'fully pushed (as of your last fetch)'
      : `${recoverable === 'no' ? 'not recoverable' : recoverable === 'partly' ? 'only partly recoverable' : 'see the folder details'}: ${because}`
  return { level, recoverable, because, headline, onlyRepos, gitLine: bits.length ? bits.join(' · ') : undefined, stake }
}

// ---- words --------------------------------------------------------------------------------------

function render(s: Scan, v: Verdict, crit: Critical | undefined, ctx: FolderContext): FolderRisk {
  const rows: Row[] = []
  const name = (p: string) => (p.startsWith(s.dir + '/') ? p.slice(s.dir.length + 1) : p)
  if (crit) rows.push(['Target', cap1(crit.reason)])

  // where it sits
  if (s.git?.isRoot) rows.push(['Where', 'Repository root · its history goes too'])
  else if (s.git) rows.push(['Where', `Inside repository ${clip(s.git.root, 60)}`])
  else rows.push(['Where', 'Outside git · no history, no remote'])
  if (s.git?.isRoot && s.whole?.atStake) rows.push(['Local only', s.whole.text.replace(/^.*?\/ {2}/, '')])
  if (s.nested.length)
    rows.push(['Includes', `${plural(s.nested.length + s.nestedMore, 'repository', 'repositories')}, .git too: ${s.nested.map(n => clip(n.text.replace(s.dir + '/', ''), 80)).join('; ')}${s.nestedMore ? `; +${s.nestedMore} more` : ''}`])

  // what kind of content
  const bits: string[] = []
  if (s.ctxRegen) bits.push(`all build output (${s.ctxRegen})`)
  for (const cls of ['data', 'secret', 'source', 'other'] as const) {
    const m = s.entries.filter(e => e.cls === cls && !e.dir)
    if (!m.length) continue
    const kb = sum(m.map(e => e.kb ?? 0))
    const sized = m.some(e => e.kb !== undefined) && (cls === 'data' || cls === 'secret')
    bits.push(`${plural(m.length, CLASS_WORDS[cls][0], CLASS_WORDS[cls][1])}${sized ? ` (${kbText(kb)}${m.some(e => e.kb === undefined) ? '+' : ''})` : ''}`)
  }
  const regen = s.entries.filter(e => e.cls === 'regen' && e.dir && e.path !== s.dir).sort((a, b) => (b.kb ?? 0) - (a.kb ?? 0))
  if (regen.length)
    bits.push(`build output: ${regen.slice(0, 3).map(e => `${name(e.path)}/${e.kb !== undefined ? ` ${kbText(e.kb)}` : ''}`).join(', ')}${regen.length > 3 ? `, +${regen.length - 3} more` : ''}`)
  const committedGeneric = s.entries.filter(e => e.dir && e.cls === 'source')
  if (committedGeneric.length) bits.push(`${committedGeneric.map(e => name(e.path) + '/').join(', ')} hold tracked files`)
  if (ctx.note) bits.push(ctx.note)
  if (s.sampled) bits.push(`sampled: first ${fmt(SAMPLE_CAP)} of ${fmt(s.listed)}${s.listed > SAMPLE_CAP ? '' : '+'} files`)
  rows.push(['Contains', bits.length ? bits.join(' · ') : s.nested.length ? 'only the repositories above' : 'nothing'])

  // size and recency
  const size = [s.totalKb !== undefined ? kbText(s.totalKb) : undefined, s.files !== undefined ? `${fmt(s.files)}${s.filesLowerBound ? '+' : ''} ${s.files === 1 && !s.filesLowerBound ? 'file' : 'files'}` : undefined].filter(Boolean) as string[]
  if (s.newest) size.push(s.newestMins === undefined ? s.newest : `last edit ${s.newest}`)
  if (s.newestMins !== undefined && s.newestMins <= 1440) size.push('likely active work')
  if (size.length) rows.push(['Size', size.join(' · ')])

  if (v.gitLine && s.mode !== 'modify') rows.push(['Git', v.gitLine])
  if (v.stake.length) rows.push(['At stake', `${v.stake.slice(0, 3).map(x => clip(x, 50)).join(', ')}${v.stake.length > 3 ? `, +${v.stake.length - 3} more` : ''}`])

  const hints: string[] = []
  if (s.partial) hints.push('Scan stopped early (slow disk or huge folder): figures are partial')
  const sync = syncHint(s.dir, ctx.home)
  if (sync) hints.push(sync)
  if (s.links > 0) hints.push(`${plural(s.links, 'symlink')} inside: only the links are removed, not their targets`)
  if (s.crossesFs) hints.push('Includes another filesystem (a mounted drive?): rm -r follows it unless run with --one-file-system')
  for (const h of hints.slice(0, 2)) rows.push(['Note', clip(h, 140)])
  rows.push(['Recoverable', `${cap1(v.recoverable)} · ${v.because}`])

  return {
    path: s.dir, title: `${dirLabel(s.dir, ctx)} · ${LEVEL_WORD[v.level]}`, level: v.level, rows, headline: v.headline,
    regenerable: s.entries.length > 0 && s.entries.every(e => e.cls === 'regen'), complete: !s.partial, onlyRepos: v.onlyRepos,
  }
}
const name2 = (p: string, root: string) => p.slice(root.length + 1)

// ---- symbolic links and unscanned folders -------------------------------------------------------

async function symlinkRisk(light: Run, dir: string, ctx: FolderContext, crit: Critical | undefined): Promise<FolderRisk> {
  const toDir = lines((await light(['find', '-L', dir, '-maxdepth', '0', '-type', 'd', '-print'])).stdout).length > 0
  const act: Record<Mode, string> = {
    delete: 'rm removes only the link. A trailing slash (link/) can reach the target, so check how it is written',
    modify: 'chmod -R changes the target of a link named on the command line; chown may change the link itself',
    overwrite: 'cp or mv -f replaces the link or writes through it; the target was not inspected',
  }
  const level: RiskLevel = ctx.mode === 'delete' && !crit ? 'low' : 'medium'
  const rows: Row[] = []
  if (crit) rows.push(['Target', cap1(crit.reason)])
  rows.push(['What', `Symbolic link ${toDir ? 'to a folder' : 'to a file (or broken)'} · the target was not inspected`])
  rows.push(['Effect', act[ctx.mode]])
  const sync = syncHint(dir, ctx.home)
  if (sync) rows.push(['Note', sync])
  rows.push(['Recoverable', ctx.mode === 'delete' ? 'Yes · only the link goes; the target keeps its content' : 'Unknown · the target was not inspected'])
  return { path: dir, title: `${dirLabel(dir, ctx)} (symlink) · ${LEVEL_WORD[level]}`, level, rows, headline: ctx.mode === 'delete' ? 'a symlink: only the link goes, not its target' : 'a symlink: its target was not inspected', regenerable: false, complete: ctx.mode === 'delete' }
}

const dirLabel = (dir: string, ctx: FolderContext) => (dir === '/' ? '/' : `${ctx.runCwd && dir.startsWith(ctx.runCwd + '/') ? name2(dir, ctx.runCwd) : dir}/`)

function unscanned(dir: string, crit: Critical | undefined, ctx: FolderContext, why: string): FolderRisk {
  const level: RiskLevel = crit ? 'high' : 'unknown'
  const rows: Row[] = []
  if (crit) rows.push(['Target', cap1(crit.reason)])
  rows.push(['Scan', `Skipped · ${why}`])
  const hint = syncHint(dir, ctx.home)
  if (hint) rows.push(['Note', hint])
  if (crit && ctx.mode === 'modify')
    rows.push(['Recoverable', `Partly · contents stay, but old permissions and owners are not recorded; changing them across ${crit.reason} can break ssh keys and system files`])
  else rows.push(['Recoverable', crit ? 'No · assume everything is gone (backups such as Time Machine are not checked)' : 'Unknown · nothing was inspected, so assume not'])
  return {
    path: dir, title: `${dirLabel(dir, ctx)} · ${LEVEL_WORD[level]}`, level, rows,
    headline: crit ? `${cap1(crit.reason)} is targeted` : why, regenerable: false, complete: false,
  }
}

// ---- entry point --------------------------------------------------------------------------------

/** Folder risk for up to `maxFolders` directories (CRITICAL ones first). Never throws. */
export async function assessFolders(run: Run, dirs: string[], ctx: FolderContext): Promise<{ folders: FolderRisk[]; skipped: number }> {
  const ordered = [...new Set(dirs)].map(d => ({ d, c: criticalReason(d, ctx) })).sort((a, b) => Number(!!b.c) - Number(!!a.c))
  const max = ctx.maxFolders ?? 3
  const folders: FolderRisk[] = []
  for (const { d, c } of ordered.slice(0, max)) folders.push(await assessOne(run, d, c, ctx))
  return { folders, skipped: Math.max(0, ordered.length - max) }
}

async function assessOne(run: Run, dir: string, crit: Critical | undefined, ctx: FolderContext): Promise<FolderRisk> {
  const state = { slow: false, failed: undefined as string | undefined }
  // light probes (git, type tests) throw to the caller; heavy ones (tree walks) stop the scan at the first timeout
  const light: Run = (argv, cwd) => run(argv, cwd, { timeoutMs: FOLDER_PROBE_MS })
  const heavy: Probe = async (argv, cwd) => {
    if (state.slow) return undefined
    try {
      return await run(argv, cwd, { timeoutMs: FOLDER_PROBE_MS })
    } catch (err) {
      state.slow = true
      state.failed = (err as Error).message || 'probe failed'
      return undefined
    }
  }
  try {
    const link = lines((await light(['find', dir, '-maxdepth', '0', '-type', 'l', '-print'])).stdout).length > 0
    if (link) return await symlinkRisk(light, dir, ctx, crit)
    if (crit?.skipScan) return unscanned(dir, crit, ctx, 'too broad to inspect')
    const s = await scanFolder(light, heavy, state, dir, ctx)
    return render(s, judge(s, crit), crit, ctx)
  } catch (err) {
    return unscanned(dir, crit, ctx, `could not scan (${clip((err as Error).message || 'probe failed', 100)})`)
  }
}

files.hooks/recover.ts:
// The recoverability check: for paths that are about to be deleted, overwritten or emptied,
// say what can NOT be got back. READ-ONLY and argv-only like the rest of the measurer.
//
// Questions answered per path, using git where the path is inside a repository:
//   uncommitted change   tracked, but modified/staged: the edit exists only in the working tree
//   untracked            never committed: no history anywhere
//   ignored              git-ignored: data, builds, .Rdata ... not in history either
//   unpushed             committed, but on no remote branch: exists only on this machine
//   pushed and clean     recoverable (git restore, or clone) -- "as of your last fetch"
//   not in a repository  no history, no remote: gone for good
// and, for a repository that is deleted whole (its .git goes too): the local-only commits,
// stashes and uncommitted work that go with it.
//
// Contract: never throws, never says "safe" when a probe failed. A failed probe yields level
// 'unknown' with a note, and the command is held anyway (the caller already holds it).
import type { Group, Run } from './measure'

export const PUSHED_NOTE = 'Pushed means as of your last fetch'
export type RiskLevel = 'high' | 'medium' | 'low' | 'unknown'
export type Risk = { level: RiskLevel; headline: string }
export type Assessment = { risk: Risk; groups: Group[]; notes: string[] }

type Cfg = { maxListed: number }
type Tally = { changed: string[]; untracked: string[]; ignored: string[]; unpushed: string[]; trackedClean: number }

export const GIT = ['git', '--no-optional-locks', '--no-pager', '--literal-pathspecs']
const lines = (s: string) => s.split('\n').map(l => l.replace(/\r$/, '')).filter(l => l !== '')
const n = (k: number) => k.toLocaleString('en-US')
const plural = (k: number, w: string, many = w + 's') => `${n(k)} ${k === 1 ? w : many}`
const dirname = (p: string) => (p.lastIndexOf('/') > 0 ? p.slice(0, p.lastIndexOf('/')) : '/')
const inside = (child: string, parent: string) => child === parent || child.startsWith(parent === '/' ? '/' : parent + '/')
const chunks = <T>(a: T[], size: number) => Array.from({ length: Math.ceil(a.length / size) }, (_, k) => a.slice(k * size, (k + 1) * size))
const cap = (title: string, rows: string[], max: number, flags: { subset?: boolean; extra?: boolean } = {}): Group => ({ title, rows: rows.slice(0, max), more: Math.max(0, rows.length - max), ...flags })

const LABELS: Record<string, string> = { ' M': 'modified', 'M ': 'staged', MM: 'staged+modified', 'A ': 'new (staged)', AM: 'new+modified', ' T': 'type changed', 'R ': 'renamed (staged)', UU: 'CONFLICT' }
const label = (xy: string) => LABELS[xy] ?? `changed (${xy.trim() || xy})`

/** `git status --porcelain=v1 -z` as raw entries: the two status letters and the path (repository-root relative). */
export function statusEntries(out: string): { xy: string; path: string }[] {
  const res: { xy: string; path: string }[] = []
  const toks = out.split('\0')
  for (let i = 0; i < toks.length; i++) {
    const t = toks[i]!
    if (t.length < 4) continue
    const xy = t.slice(0, 2)
    if (xy[0] === 'R' || xy[0] === 'C') i++ // the next token is the rename's original path
    res.push({ xy, path: t.slice(3) })
  }
  return res
}

/** `git status --porcelain=v1 -z` into change classes. Paths are relative to the repository root. */
export function parseStatusZ(out: string): { changed: string[]; untracked: string[]; ignored: string[] } {
  const res = { changed: [] as string[], untracked: [] as string[], ignored: [] as string[] }
  for (const { xy, path } of statusEntries(out)) {
    if (xy === '??') res.untracked.push(path)
    else if (xy === '!!') res.ignored.push(path)
    else if (xy[1] === 'D' && xy[0] === ' ') continue // already gone from the working tree
    else if (xy[0] === 'D' && xy[1] === ' ') continue // staged removal, nothing left to lose
    else res.changed.push(`${label(xy)}  ${path}`)
  }
  return res
}

async function git(run: Run, cwd: string, ...argv: string[]) {
  return run([...GIT, ...argv], cwd)
}

async function dirsAmong(run: Run, paths: string[]): Promise<Set<string>> {
  const found = new Set<string>()
  for (const part of chunks(paths, 60))
    for (const l of lines((await run(['find', ...part, '-maxdepth', '0', '-type', 'd', '-print'])).stdout)) found.add(l)
  return found
}

async function countFiles(run: Run, dir: string): Promise<number> {
  const res = await run(['find', dir, '!', '-type', 'd', '-print'])
  return lines(res.stdout).length
}

/** Repositories wholly inside a deleted directory (their .git goes too). */
async function nestedRepos(run: Run, dirs: string[]): Promise<string[]> {
  const roots = new Set<string>()
  for (const d of dirs.slice(0, 20)) {
    const res = await run(['find', d, '-maxdepth', '6', '-name', '.git', '-prune', '-print'])
    for (const l of lines(res.stdout)) if (l.endsWith('/.git')) roots.add(l.slice(0, -5))
  }
  return [...roots].slice(0, 20)
}

export async function assessLoss(run: Run, paths: string[], cfg: Cfg): Promise<Assessment> {
  const out: Assessment = { risk: { level: 'unknown', headline: '' }, groups: [], notes: [] }
  try {
    return await assess(run, [...new Set(paths)].slice(0, 500), cfg)
  } catch (err) {
    out.risk.headline = 'could not check what git could restore: assume nothing is recoverable'
    out.notes.push(`risk check failed: ${(err as Error).message || 'probe failed'}`)
    return out
  }
}

async function assess(run: Run, paths: string[], cfg: Cfg): Promise<Assessment> {
  const notes: string[] = []
  const dirs = await dirsAmong(run, paths)
  const dirList = [...dirs]

  // 1. which repository (if any) holds each path; repos that are deleted whole count as scopes of their own
  const scopes = new Map<string, string[]>() // repo root -> paths inside it
  const outside: string[] = []
  const rootOf = new Map<string, string | null>()
  for (const p of paths) {
    const probe = dirs.has(p) ? p : dirname(p)
    if (!rootOf.has(probe)) {
      const res = await git(run, probe, 'rev-parse', '--show-toplevel')
      rootOf.set(probe, res.exitCode === 0 ? res.stdout.trim() : null)
    }
    const root = rootOf.get(probe)
    if (root) scopes.set(root, [...(scopes.get(root) ?? []), p])
    else outside.push(p)
  }
  const whole = new Set<string>()
  for (const root of scopes.keys()) if (dirs.has(root) && paths.includes(root)) whole.add(root)
  for (const r of await nestedRepos(run, dirList)) {
    whole.add(r)
    if (!scopes.has(r)) scopes.set(r, [r])
  }

  // 2. per repository: uncommitted, untracked, ignored, unpushed
  const total: Tally = { changed: [], untracked: [], ignored: [], unpushed: [], trackedClean: 0 }
  const wholeFacts: string[] = []
  let wholeAtStake = 0
  let noRemote = false
  for (const [root, inRepo] of scopes) {
    const remotes = lines((await git(run, root, 'remote')).stdout)
    const t = await tally(run, root, inRepo, cfg, notes, remotes.length > 0)
    total.changed.push(...t.changed)
    total.untracked.push(...t.untracked)
    total.ignored.push(...t.ignored)
    total.unpushed.push(...t.unpushed)
    total.trackedClean += t.trackedClean
    if (remotes.length === 0) noRemote = true
    if (whole.has(root)) {
      const fact = await wholeRepoFact(run, root, remotes.length === 0)
      wholeFacts.push(fact.text)
      if (fact.atStake) wholeAtStake++
    }
  }

  // 3. words
  const groups: Group[] = []
  const max = cfg.maxListed
  if (wholeFacts.length) groups.push(cap('Whole repositories inside (their history goes too)', wholeFacts, max, { extra: true }))
  if (total.changed.length) groups.push(cap('Uncommitted changes (gone for good)', total.changed, max))
  if (total.untracked.length) groups.push(cap('Untracked, never committed (gone for good)', total.untracked, max, { subset: true }))
  if (total.ignored.length) groups.push(cap('Git-ignored (gone unless you can regenerate them)', total.ignored, max, { subset: true }))
  if (total.unpushed.length)
    groups.push(cap('Committed, not pushed (only in this .git)', total.unpushed, max))
  if (outside.length) groups.push(cap('Outside git, no history or remote (gone for good)', outside, max, { subset: true }))

  const lostForever = total.changed.length + total.untracked.length + total.ignored.length + outside.length
  const bits: string[] = []
  if (total.changed.length) bits.push(`${plural(total.changed.length, 'file')} with uncommitted changes`)
  if (total.untracked.length) bits.push(`${plural(total.untracked.length, 'untracked path')}`)
  if (total.ignored.length) bits.push(`${plural(total.ignored.length, 'git-ignored path')}`)
  if (outside.length) bits.push(`${plural(outside.length, 'path')} outside any repository`)
  if (total.unpushed.length) bits.push(`${plural(total.unpushed.length, 'unpushed commit')} touching these paths`)
  if (wholeFacts.length) bits.push(`${plural(wholeFacts.length, 'whole repository', 'whole repositories')}`)

  let risk: Risk
  // a repository deleted whole is only a hard loss when something exists nowhere else: commits on no remote, stashes,
  // linked worktrees, or no remote at all. A clean, fully pushed one comes back with a fresh clone.
  const hardLoss = total.changed.length + total.untracked.length + outside.length + total.unpushed.length + wholeAtStake
  if (hardLoss > 0) risk = { level: 'high', headline: `${bits.join(', ')}: none of it is on a remote` }
  else if (total.ignored.length > 0) risk = { level: 'medium', headline: `${bits.join(', ')}: not in version control` }
  else if (scopes.size > 0)
    risk = {
      level: 'low',
      headline: noRemote
        ? `${plural(total.trackedClean, 'tracked file')} committed locally (no remote): git restore works while .git stays`
        : `${plural(total.trackedClean, 'tracked file')} pushed (as of your last fetch): git restore or a fresh clone brings them back${wholeFacts.length ? ', no local-only commits or stashes' : ''}`,
    }
  else risk = { level: 'unknown', headline: 'nothing to assess' }

  if (noRemote && scopes.size > 0) notes.push('No remote: every commit exists only on this machine')
  if (lostForever === 0 && total.unpushed.length === 0 && wholeFacts.length === 0) notes.push(PUSHED_NOTE)
  return { risk, groups, notes }
}

async function tally(run: Run, root: string, inRepo: string[], cfg: Cfg, notes: string[], hasRemote: boolean): Promise<Tally> {
  const t: Tally = { changed: [], untracked: [], ignored: [], unpushed: [], trackedClean: 0 }
  const specs = inRepo.slice(0, 200)
  const st = await git(run, root, 'status', '--porcelain=v1', '-z', '--ignored', '--', ...specs)
  if (st.exitCode !== 0) throw new Error(`git status failed in ${root}: ${st.stderr.trim().split('\n')[0] || `exit ${st.exitCode}`}`)
  if (st.isStdoutTruncated) notes.push(`${root}: git status output was truncated, counts are lower bounds`)
  const parsed = parseStatusZ(st.stdout)
  t.changed = parsed.changed
  // a collapsed directory ("build/") stands for many files: say how many
  const expand = async (entries: string[]) => {
    const rows: string[] = []
    let looked = 0
    for (const e of entries) {
      if (e.endsWith('/') && looked < 10) {
        looked++
        const count = await countFiles(run, `${root}/${e.replace(/\/$/, '')}`)
        rows.push(`${e}  (${plural(count, 'file')})`)
      } else rows.push(e)
    }
    return rows
  }
  t.untracked = await expand(parsed.untracked)
  t.ignored = await expand(parsed.ignored)

  const ls = await git(run, root, 'ls-files', '-z', '--', ...specs)
  const tracked = ls.stdout.split('\0').filter(Boolean).length
  t.trackedClean = Math.max(0, tracked - parsed.changed.length)

  // without any remote every commit is "unpushed": that says nothing about these paths, so it is a note instead
  if (hasRemote) {
    const unpushed = await git(run, root, 'log', '--format=%h %s', '-n', String(cfg.maxListed + 1), 'HEAD', '--not', '--remotes', '--', ...specs)
    if (unpushed.exitCode === 0) t.unpushed = lines(unpushed.stdout)
  }
  // an empty repository (no HEAD yet) makes `git log HEAD` fail: that is not an error worth stopping for
  return t
}

/** What a whole repository would take with it. `atStake` is true when any of it exists nowhere else. */
export async function wholeRepoFact(run: Run, root: string, noRemote: boolean): Promise<{ text: string; atStake: boolean }> {
  const local = await git(run, root, 'rev-list', '--count', '--branches', '--tags', '--not', '--remotes')
  const stash = await git(run, root, 'stash', 'list')
  const wt = await git(run, root, 'worktree', 'list')
  const localCommits = local.exitCode === 0 ? Number(local.stdout.trim()) || 0 : undefined
  const stashes = lines(stash.stdout).length
  const worktrees = lines(wt.stdout).length - 1
  const bits = [
    localCommits !== undefined ? `${plural(localCommits, 'commit')} on no remote` : 'local-only commits unknown',
    `${plural(stashes, 'stash', 'stashes')}`,
  ]
  if (worktrees > 0) bits.push(`${plural(worktrees, 'linked worktree')}`)
  if (noRemote) bits.push('no remote')
  return {
    text: `${root}/  ${bits.join(', ')}`,
    atStake: localCommits === undefined || localCommits > 0 || stashes > 0 || worktrees > 0 || noRemote,
  }
}

