{
  "name": "command-guard",
  "version": "0.3.3",
  "types": "./types/index.d.ts",
  "description": "Holds risky Bash commands (rm -rf, git reset --hard, force push, DROP TABLE ...), shows exactly what they would destroy, and asks first. A safety net, not a permission system.",
  "author": {
    "name": "Samuel Fernandes"
  },
  "userConfig": {
    "maxListed": {
      "type": "number",
      "title": "Rows to list",
      "description": "Most files, commits or paths listed in the confirmation (the rest is counted as +N more).",
      "default": 5
    },
    "askFrom": {
      "type": "string",
      "title": "Ask from risk level",
      "description": "The lowest risk level that opens the dialog. medium (default): low-risk commands run without a dialog. high: only high and unknown. low: ask about everything. A command that could not be checked (unknown) always asks.",
      "default": "medium"
    },
    "extraPatterns": {
      "type": "string",
      "multiple": true,
      "title": "Extra patterns",
      "description": "Regular expressions; a Bash command matching any of them is held too (nothing is measured for these)."
    }
  }
}

